/**
 * Reconnaissance et normalisation des DOI, et extraction depuis une URL.
 *
 * C'est la première pièce de la porte d'entrée unique (§3.3) : quel que soit
 * ce qu'on colle — un DOI nu, une URL d'éditeur, une page PubMed — on cherche
 * d'abord à en tirer un identifiant sur lequel tout le reste s'accroche.
 */

// Un DOI est « 10. » + un préfixe d'enregistrement + « / » + un suffixe libre.
// Le suffixe accepte presque tout, d'où la nécessité de rogner ensuite la
// ponctuation collée par le contexte (parenthèse fermante, point final...).
const MOTIF_DOI = /10\.\d{4,9}\/[-._;()/:a-z0-9<>[\]+]+/i;

/** Ponctuation qu'une phrase colle à la fin d'un DOI sans en faire partie. */
function rogner(doi) {
  let sortie = doi;
  while (sortie.length && /[.,;:'")\]]/.test(sortie.at(-1))) {
    // Une parenthèse fermante appartient au DOI si elle est ouverte dedans,
    // ce qui arrive réellement (ex. 10.1002/(SICI)1097-0258...).
    if (sortie.at(-1) === ')' && compte(sortie, '(') > compte(sortie, ')') - 1) break;
    sortie = sortie.slice(0, -1);
  }
  return sortie;
}

const compte = (chaine, caractere) => chaine.split(caractere).length - 1;

/** Forme canonique : minuscules, sans préfixe de résolveur. */
export function normaliserDoi(brut) {
  if (!brut) return null;
  const trouve = MOTIF_DOI.exec(String(brut).trim());
  return trouve ? rogner(trouve[0]).toLowerCase() : null;
}

export const estDoi = (valeur) => normaliserDoi(valeur) !== null;

/** Tous les DOI distincts d'un texte, dans l'ordre d'apparition. */
export function extraireDois(texte) {
  if (!texte) return [];
  const motif = new RegExp(MOTIF_DOI.source, 'gi');
  const vus = new Set();
  for (const trouve of String(texte).matchAll(motif)) {
    vus.add(rogner(trouve[0]).toLowerCase());
  }
  return [...vus];
}

/** PMID lu dans une URL PubMed, ou null. */
export function pmidDepuisUrl(url) {
  const trouve = /pubmed\.ncbi\.nlm\.nih\.gov\/(\d{4,9})/i.exec(String(url ?? ''));
  return trouve ? trouve[1] : null;
}

/** PMCID lu dans une URL PubMed Central, ou null. */
export function pmcidDepuisUrl(url) {
  const trouve = /pmc\/articles\/(PMC\d+)/i.exec(String(url ?? ''));
  return trouve ? trouve[1].toUpperCase() : null;
}

/**
 * DOI reconstitué à partir d'une URL d'éditeur qui ne le contient pas.
 *
 * Beaucoup d'éditeurs construisent leur adresse à partir du suffixe du DOI
 * sans jamais écrire le préfixe. `bmj.com/content/394/bmj-2026-100216`
 * désigne ainsi `10.1136/bmj-2026-100216`, mais aucune expression régulière
 * cherchant « 10.xxxx/ » ne peut le voir. Sans cette table, coller l'adresse
 * d'un article du BMJ ouvre un formulaire entièrement vide.
 *
 * Le garde-fou est le second groupe de chaque motif : il exige un identifiant
 * contenant des lettres. Sans lui, `jnnp.bmj.com/content/95/9/812` prendrait
 * le numéro de page « 812 » pour un identifiant et fabriquerait un DOI qui
 * n'existe pas.
 *
 * Le DOI obtenu n'est pas cru sur parole : `enrich.js` l'envoie à Crossref,
 * qui confirme ou non son existence.
 */
const MOTIFS_EDITEURS = [
  // BMJ et toutes ses revues (jnnp, gut, heart, bmjopen…)
  { motif: /(?:^|\.)bmj\.com\/content\/(?:[\w.]+\/)?([a-z]+[\w.-]*-[\w.-]+)/i, prefixe: '10.1136' },
  // Nature et le portefeuille Springer Nature
  { motif: /nature\.com\/articles\/([a-z]\w*[-\w.]*)/i, prefixe: '10.1038' },
  // BioMed Central
  { motif: /biomedcentral\.com\/articles\/(10\.\d{4,9}\/[-._;()/:\w]+)/i, prefixe: null },
];

/**
 * Identifiant Elsevier (PII) lu dans une adresse ScienceDirect ou Lancet.
 *
 * Les deux familles se ressemblent mais ne se résolvent pas pareil, d'où la
 * distinction :
 *   - le Lancet écrit « PIIS2215-0366(25)00202-0 », et le DOI est ce PII
 *     préfixé de 10.1016 ;
 *   - ScienceDirect écrit « S0165178126004373 », dont aucune règle ne permet
 *     de déduire le DOI — mais Elsevier le dépose chez Crossref comme
 *     identifiant alternatif, ce qui le rend interrogeable.
 */
export function piiDepuisUrl(url) {
  const texte = String(url ?? '');

  // Le Lancet d'abord : sa forme est plus spécifique et serait sinon
  // absorbée par le motif de ScienceDirect.
  const lancet = /\/article\/PII(S[\d-]+\(\d+\)[\d-]+X?)/i.exec(texte);
  if (lancet) return { pii: lancet[1], famille: 'lancet' };

  const sciencedirect = /\/pii\/([SB]\d{4}[\w-]*\w)/i.exec(texte);
  if (sciencedirect) return { pii: sciencedirect[1], famille: 'elsevier' };

  return null;
}

export function doiDepuisUrlEditeur(url) {
  const texte = String(url ?? '');
  for (const { motif, prefixe } of MOTIFS_EDITEURS) {
    const trouve = motif.exec(texte);
    if (!trouve) continue;
    const identifiant = trouve[1];
    // Un identifiant purement numérique est un numéro de page ou de volume.
    if (!/[a-z]/i.test(identifiant)) continue;
    const candidat = prefixe ? `${prefixe}/${identifiant}` : identifiant;
    const normalise = normaliserDoi(candidat);
    if (normalise) return normalise;
  }
  return null;
}

/**
 * Analyse une saisie libre et dit ce qu'on tient.
 *
 * Renvoie `{ genre, doi, pmid, pmcid, url }` où `genre` vaut 'doi', 'pmid',
 * 'pmcid', 'url' ou 'inconnu'. Le champ `url` est conservé même quand un DOI
 * a été trouvé : il sert de lien de repli si l'enrichissement échoue.
 */
export function analyserEntree(saisie) {
  const texte = String(saisie ?? '').trim();
  if (!texte) return { genre: 'inconnu', doi: null, pmid: null, pmcid: null, url: null };

  const url = /^https?:\/\//i.test(texte) ? texte : null;

  // Un DOI présent dans l'URL prime : c'est la clé la plus riche, elle ouvre
  // Crossref, PubMed et Unpaywall d'un coup.
  const doi = normaliserDoi(texte);
  if (doi) return { genre: 'doi', doi, pmid: pmidDepuisUrl(texte), pmcid: pmcidDepuisUrl(texte), url };

  const pmid = pmidDepuisUrl(texte) ?? (/^\d{5,9}$/.test(texte) ? texte : null);
  if (pmid) return { genre: 'pmid', doi: null, pmid, pmcid: null, url };

  const pmcid = pmcidDepuisUrl(texte) ?? (/^PMC\d+$/i.test(texte) ? texte.toUpperCase() : null);
  if (pmcid) return { genre: 'pmcid', doi: null, pmid: null, pmcid, url };

  // Dernier recours avant d'abandonner : l'adresse d'un éditeur qui construit
  // ses URL sur le suffixe du DOI sans jamais écrire le préfixe.
  const devine = doiDepuisUrlEditeur(texte);
  if (devine) return { genre: 'doi', doi: devine, pmid: null, pmcid: null, url, deduit: true };

  if (url) return { genre: 'url', doi: null, pmid: null, pmcid: null, url };
  return { genre: 'inconnu', doi: null, pmid: null, pmcid: null, url: null };
}

export const urlDoi = (doi) => (doi ? `https://doi.org/${doi}` : null);
export const urlPubmed = (pmid) => (pmid ? `https://pubmed.ncbi.nlm.nih.gov/${pmid}/` : null);
