/**
 * PubMed / NCBI E-utilities — abstract et termes MeSH (§3.3).
 *
 * Les MeSH sont l'apport décisif : ce sont des mots-clés posés par des
 * indexeurs humains sur un vocabulaire contrôlé. C'est ce qui évite de se
 * retrouver six mois plus tard avec « catatonie », « catatonia » et
 * « Catatonie » comme trois tags distincts.
 *
 * Aucune clé d'API n'est nécessaire en dessous de 3 requêtes/seconde ; on
 * reste très en dessous puisqu'on capture une référence à la fois.
 */

import { XMLParser } from 'fast-xml-parser';
import { getJSON, getText } from './http.js';

const EUTILS = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils';

const analyseur = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@',
  // Sans cela, une balise unique donne un objet et deux balises un tableau :
  // on force le tableau sur les nœuds répétables pour ne pas semer des
  // `Array.isArray` dans tout le fichier.
  isArray: (nom) =>
    ['Author', 'MeshHeading', 'QualifierName', 'PublicationType', 'AbstractText', 'ArticleId'].includes(nom),
});

const NOMMEES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };

/**
 * Décode les références de caractères laissées par le flux MEDLINE.
 *
 * Indispensable et non cosmétique : PubMed encode les caractères accentués en
 * références numériques, si bien qu'un auteur nommé Deschênes ressort en
 * « Desch&#xea;nes ». Sans ce décodage, presque tous les noms français de la
 * collection seraient abîmés — y compris dans le nom de fichier de la fiche.
 *
 * `&amp;` est traité en dernier, sans quoi « &amp;#xe9; » se décoderait deux
 * fois et produirait un caractère qui n'était pas dans la source.
 */
function decoder(chaine) {
  return chaine
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)))
    .replace(/&(lt|gt|quot|apos|nbsp);/g, (_, nom) => NOMMEES[nom])
    .replace(/&amp;/g, '&');
}

/** Concatène le texte d'un nœud, que fast-xml-parser l'ait aplati ou non. */
function texte(noeud) {
  if (noeud == null) return '';
  if (typeof noeud === 'string') return decoder(noeud);
  if (typeof noeud === 'number') return String(noeud);
  if (Array.isArray(noeud)) return noeud.map(texte).join(' ');
  return texte(noeud['#text']);
}

/** DOI ou PMID → PMID, via la recherche indexée. */
export async function trouverPmid({ doi, pmid }) {
  if (pmid) return String(pmid);
  if (!doi) return null;
  const url = new URL(`${EUTILS}/esearch.fcgi`);
  url.searchParams.set('db', 'pubmed');
  url.searchParams.set('term', `${doi}[DOI]`);
  url.searchParams.set('retmode', 'json');
  const donnees = await getJSON(url.toString());
  return donnees?.esearchresult?.idlist?.[0] ?? null;
}

/**
 * Recompose l'abstract structuré.
 *
 * PubMed découpe souvent l'abstract en sections étiquetées (Background,
 * Methods, Results...). On conserve ces étiquettes : à la relecture six mois
 * plus tard, sauter directement aux résultats vaut largement les quelques
 * caractères que ça coûte.
 */
function abstract(article) {
  const morceaux = article?.Abstract?.AbstractText;
  if (!morceaux) return null;
  const rendu = morceaux
    .map((morceau) => {
      const corps = texte(morceau).trim();
      if (!corps) return null;
      const etiquette = morceau?.['@Label'];
      return etiquette ? `${etiquette} : ${corps}` : corps;
    })
    .filter(Boolean)
    .join('\n\n');
  return rendu || null;
}

function auteurs(article) {
  return (article?.AuthorList?.Author ?? [])
    .map((a) => {
      if (a.CollectiveName) return texte(a.CollectiveName);
      const nom = texte(a.LastName).trim();
      const prenom = texte(a.ForeName).trim() || texte(a.Initials).trim();
      return [prenom, nom].filter(Boolean).join(' ').trim();
    })
    .filter(Boolean);
}

/**
 * Termes MeSH, en distinguant les descripteurs majeurs.
 *
 * Un descripteur « majeur » (`MajorTopicYN="Y"`) désigne un sujet central de
 * l'article, pas un sujet incident. C'est le signal qui permettra à
 * `tags.js` de proposer huit tags utiles plutôt que vingt-cinq.
 */
function mesh(article) {
  return (article?.MeshHeadingList?.MeshHeading ?? [])
    .map((entree) => {
      const descripteur = entree?.DescriptorName;
      const nom = texte(descripteur).trim();
      if (!nom) return null;
      const majeurQualifie = (entree?.QualifierName ?? []).some((q) => q?.['@MajorTopicYN'] === 'Y');
      return {
        terme: nom,
        identifiant: descripteur?.['@UI'] ?? null,
        majeur: descripteur?.['@MajorTopicYN'] === 'Y' || majeurQualifie,
      };
    })
    .filter(Boolean);
}

function annee(article) {
  const date = article?.Journal?.JournalIssue?.PubDate;
  const brut = texte(date?.Year) || texte(date?.MedlineDate);
  const trouve = /\d{4}/.exec(brut);
  return trouve ? Number(trouve[0]) : null;
}

/** Notice complète pour un PMID. */
export async function chercherParPmid(pmid) {
  const url = new URL(`${EUTILS}/efetch.fcgi`);
  url.searchParams.set('db', 'pubmed');
  url.searchParams.set('id', String(pmid));
  url.searchParams.set('retmode', 'xml');

  const brut = await getText(url.toString(), { accept: 'application/xml' });
  const arbre = analyseur.parse(brut);

  const citation = arbre?.PubmedArticleSet?.PubmedArticle?.MedlineCitation;
  const article = citation?.Article;
  if (!article) return null;

  const identifiants = arbre?.PubmedArticleSet?.PubmedArticle?.PubmedData?.ArticleIdList?.ArticleId ?? [];
  const doi = identifiants.find((i) => i?.['@IdType'] === 'doi');
  const pmcid = identifiants.find((i) => i?.['@IdType'] === 'pmc');

  return {
    source: 'pubmed',
    pmid: String(texte(citation.PMID) || pmid),
    doi: doi ? texte(doi).toLowerCase() : null,
    pmcid: pmcid ? texte(pmcid).toUpperCase() : null,
    titre: texte(article.ArticleTitle).replace(/\s+/g, ' ').replace(/\.$/, '').trim() || null,
    auteurs: auteurs(article),
    // Titre complet de la revue plutôt que l'abrégé MEDLINE : c'est celui
    // qu'on affiche en italique sous le titre.
    revue: texte(article.Journal?.Title).trim() || null,
    annee: annee(article),
    volume: texte(article.Journal?.JournalIssue?.Volume).trim() || null,
    numero: texte(article.Journal?.JournalIssue?.Issue).trim() || null,
    pages: texte(article.Pagination?.MedlinePgn).trim() || null,
    abstract: abstract(article),
    mesh: mesh(citation),
    types_publication: (article.PublicationTypeList?.PublicationType ?? []).map(texte).filter(Boolean),
  };
}

/** Raccourci : DOI → notice PubMed, ou null si l'article n'y est pas indexé. */
export async function chercherParDoi(doi) {
  const pmid = await trouverPmid({ doi });
  return pmid ? chercherParPmid(pmid) : null;
}
