/**
 * Application de capture mobile (§3.3, §3.4, V2 du cahier des charges).
 *
 * Point d'entrée unique, écran de validation en quinze secondes, écriture
 * directe dans le dépôt GitHub. Aucune étape ne passe par un serveur : cette
 * page appelle Crossref, PubMed, Unpaywall, OpenAlex et l'API GitHub
 * directement depuis le téléphone.
 *
 * C'est le même moteur que la CLI (`bin/veille.js`) : voir `core/enrich.js`.
 * Toute règle de capture doit vivre là-bas, jamais ici.
 */

import { analyserEntree } from '../core/doi.js';
import { enrichir, enrichirDepuisTexte } from '../core/enrich.js';
import { extraireDoiPdf } from '../core/pdf.js';
import { normaliserFiche, validerFiche, serialiser, nomFichierLibre, identite, TYPES, LIBELLES_TYPE } from '../core/ref.js';
import { dedupliquerTags, normaliserTag, analyserSaisieTags } from '../core/tags.js';
import { verifierAcces, listerFiches, contenuFiche, ecrireFiche, supprimerFiche, committerFichiers, ErreurGitHub } from '../core/github.js';
import { deserialiser } from '../core/ref.js';
import traductionsMesh from './mesh-fr.generated.js';

/**
 * Adresse du site publié, déduite de celle de l'application.
 *
 * L'application est servie depuis `…/capture/` : le site est donc son dossier
 * parent. Déduire plutôt qu'écrire l'adresse en dur évite d'avoir à modifier
 * le code le jour où le site change de nom — auquel cas le lien mènerait
 * ailleurs sans que rien ne le signale.
 */
const URL_SITE = new URL('..', location.href).href;

/**
 * Empreinte du code réellement en train de tourner.
 *
 * Le paquet est publié sous un nom qui dépend de son contenu
 * (`app-GZMSSSTI.js`). Cette empreinte est donc l'identité exacte de la
 * version installée sur cet appareil, et c'est la seule façon de répondre à
 * « je n'ai pas la nouvelle version » autrement qu'en devinant : on la lit
 * dans les réglages et on la compare. Elle est tirée de la balise qui charge
 * le paquet, et non de `import.meta.url`, pour que le code reste évaluable
 * hors module — c'est ainsi que les tests l'exécutent.
 */
const VERSION =
  /app-([A-Z0-9]+)\.js/.exec(document.querySelector('script[src*="app-"]')?.src ?? '')?.[1] ??
  'développement';

const CLE_CONFIG = 'veille.config.v1';
const CLE_VOCABULAIRE = 'veille.vocabulaire.v1';
// Contenu des fiches, indexé par l'empreinte GitHub du fichier. Voir
// `lireFiches` : c'est ce qui évite de retélécharger toute la collection à
// chaque ouverture.
const CLE_FICHES = 'veille.fiches.v1';

/**
 * Mots-clés déjà employés dans la collection, pour les proposer à la saisie.
 *
 * Chargés depuis `tags.json`, produit par le build à côté du site. Sans eux,
 * rien n'empêche « addicto », « addiction » et « addictologie » de coexister
 * comme trois filtres distincts pour une seule idée — et le filtrage par
 * mot-clé se scinde alors sans qu'on s'en aperçoive.
 *
 * Le dernier vocabulaire connu est conservé sur l'appareil : la saisie doit
 * continuer de proposer quelque chose hors ligne ou pendant le rechargement.
 */
let vocabulaire = [];

function vocabulaireEnCache() {
  try {
    return JSON.parse(localStorage.getItem(CLE_VOCABULAIRE) ?? '[]');
  } catch {
    return [];
  }
}

async function chargerVocabulaire() {
  vocabulaire = vocabulaireEnCache();
  try {
    const reponse = await fetch(new URL('../tags.json', location.href), { cache: 'no-cache' });
    if (!reponse.ok) return;
    const recu = await reponse.json();
    if (!Array.isArray(recu)) return;
    vocabulaire = recu;
    localStorage.setItem(CLE_VOCABULAIRE, JSON.stringify(recu));
    // La liste de propositions est déjà à l'écran : on la remplit sans
    // reconstruire la page, pour ne pas effacer ce qui est en cours de saisie.
    remplirPropositions();
  } catch {
    // Hors ligne : le cache fait l'affaire.
  }
}

/** Alimente la liste de propositions attachée au champ de mots-clés. */
function remplirPropositions() {
  const liste = document.getElementById('mots-cles-connus');
  if (!liste) return;
  liste.innerHTML = vocabulaire
    .map((v) => `<option value="${attr(v.tag)}">${attr(v.n > 1 ? `${v.n} fiches` : '1 fiche')}</option>`)
    .join('');
}

/**
 * Mots-clés existants proches de ce qui est tapé, sans lui être identiques.
 *
 * Le cas visé : taper « addictologie » alors que « addiction » existe déjà.
 * La liste de propositions ne le signale pas, puisqu'aucune ne commence
 * pareil une fois le mot complété. On compare donc sur la racine.
 */
function motsClesProches(saisie) {
  const cle = normaliserTag(saisie);
  if (cle.length < 4) return [];

  return vocabulaire
    .map((v) => v.tag)
    .filter((tag) => {
      const autre = normaliserTag(tag);
      if (autre === cle) return false;
      // Une racine commune d'au moins quatre lettres : « addict… ».
      const court = Math.min(cle.length, autre.length);
      let communes = 0;
      while (communes < court && cle[communes] === autre[communes]) communes++;
      return communes >= 4;
    })
    .slice(0, 4);
}
const CLE_BROUILLON = 'veille.brouillon.v1';

