async function soumettreReglages(donnees) {
  const config = {
    proprietaire: donnees.get('proprietaire').trim(),
    depot: donnees.get('depot').trim(),
    branche: donnees.get('branche').trim() || 'main',
    jeton: donnees.get('jeton').trim(),
    email: donnees.get('email').trim(),
  };
  majEtat({ erreur: null, ecran: 'attente-reglages' });
  try {
    await verifierAcces(config);
    enregistrerConfig(config);
    majEtat({ ecran: 'saisie', erreur: null });
  } catch (err) {
    majEtat({
      ecran: 'reglages',
      erreur:
        err instanceof ErreurGitHub
          ? `Accès refusé : ${err.message}`
          : "Connexion impossible. Vérifiez le nom du dépôt et votre connexion.",
    });
  }
}

