// ── Écran : validation (§3.4) — le cœur des quinze secondes ────────────

/**
 * Dit pourquoi la capture n'a rien trouvé, et ce qui va se passer.
 *
 * Un formulaire vide sans explication laisse croire à une panne, et pousse à
 * ressaisir à la main ce qui arrivera tout seul le lendemain. Les trois causes
 * ne se traitent pas pareil, d'où trois messages.
 */
function messageEchec(fiche) {
  const hote = (() => {
    try { return new URL(fiche.lien).hostname.replace(/^www\./, ''); } catch { return null; }
  })();

  // Éditeurs qui n'exposent aucun identifiant dans leur adresse et refusent la
  // lecture automatisée : vérifié, 403 et 500. Il n'y a rien à attendre, mais
  // le titre marche.
  const opaques = ['jamanetwork.com', 'cambridge.org', 'ja.ma'];
  if (hote && opaques.some((o) => hote.endsWith(o))) {
    return `<p class="avertissement">
      <strong>${texte(hote)}</strong> ne livre rien depuis son adresse, et cela ne changera pas.
      Revenez en arrière et <strong>collez le titre de l’article</strong> à la place du lien&nbsp;:
      il sera retrouvé.
    </p>`;
  }

  if (fiche.lien) {
    return `<p class="avertissement">
      Les bases bibliographiques ne connaissent pas encore cette référence — c’est
      courant pour un article paru il y a quelques jours.
      <strong>Enregistrez-la telle quelle</strong>&nbsp;: le titre, les auteurs et le résumé
      seront ajoutés automatiquement dès que les bases l’auront reçue, et elle
      n’apparaîtra sur le site et sur Telegram qu’à ce moment-là.
    </p>`;
  }

  return `<p class="avertissement">
    Aucun identifiant reconnu dans ce qui a été collé.
    Essayez un DOI, un lien PubMed, ou <strong>le titre de l’article</strong>.
  </p>`;
}

