/**
 * Lit toutes les fiches, en ne redemandant que ce qui a changé.
 *
 * GitHub livre l'empreinte de chaque fichier avec la liste du dossier. Une
 * fiche dont l'empreinte est déjà connue n'a pas à être retéléchargée : son
 * contenu est identique par construction. Sur une collection qui bouge de
 * quelques fiches par semaine, la deuxième ouverture ne demande donc presque
 * rien, là où tout relire prenait une minute.
 *
 * Le cache est conservé par empreinte et non par nom : une fiche corrigée
 * change d'empreinte et se recharge d'elle-même, sans qu'il faille penser à
 * invalider quoi que ce soit.
 */
async function lireFiches(entrees, config, surAvancement = null) {
  let cache;
  try {
    cache = JSON.parse(localStorage.getItem(CLE_FICHES) ?? '{}');
  } catch {
    cache = {};
  }

  // Sans empreinte, pas de cache : mieux vaut retélécharger que servir le
  // contenu d'une autre fiche rangée sous une clé indéfinie.
  const cleDe = (entree) => entree.sha ?? null;
  const aLire = entrees.filter((e) => !cleDe(e) || !cache[cleDe(e)]);
  let lues = 0;

  // Vingt requêtes de front : GitHub autorise plusieurs milliers d'appels par
  // heure, et c'est la latence, non le quota, qui limite ici.
  const PAR_PAQUET = 20;
  for (let i = 0; i < aLire.length; i += PAR_PAQUET) {
    const paquet = aLire.slice(i, i + PAR_PAQUET);
    await Promise.all(
      paquet.map(async (entree) => {
        const contenu = await contenuFiche(config, entree.name).catch(() => null);
        if (contenu !== null && cleDe(entree)) cache[cleDe(entree)] = contenu;
      }),
    );
    lues += paquet.length;
    surAvancement?.(Math.min(lues, aLire.length), aLire.length);
  }

  // On ne garde en cache que les empreintes encore présentes : sinon il
  // enflerait indéfiniment au fil des corrections.
  const vivantes = new Set(entrees.map(cleDe).filter(Boolean));
  const propre = {};
  for (const [sha, contenu] of Object.entries(cache)) {
    if (vivantes.has(sha)) propre[sha] = contenu;
  }
  try {
    localStorage.setItem(CLE_FICHES, JSON.stringify(propre));
  } catch {
    // Stockage plein : on continue sans cache plutôt que d'échouer.
  }

  return entrees.map((entree) => {
    const contenu = cleDe(entree) ? propre[cleDe(entree)] : null;
    return { ...(contenu ? deserialiser(contenu) : {}), nomFichier: entree.name, sha: entree.sha };
  });
}

async function ouvrirCollection() {
  const config = chargerConfig();
  majEtat({ ecran: 'attente-collection', erreur: null, aSupprimer: null, corrigee: null });
  try {
    const entrees = await listerFiches(config);
    const fiches = await lireFiches(entrees, config);
    fiches.sort((a, b) => String(b.ajoute_le ?? '').localeCompare(String(a.ajoute_le ?? '')));
    majEtat({ ecran: 'collection', collection: fiches, erreur: null });
  } catch (err) {
    majEtat({
      ecran: 'saisie',
      erreur:
        err instanceof ErreurGitHub
          ? `Lecture impossible : ${err.message}`
          : 'Lecture de la collection impossible. Vérifiez votre connexion.',
    });
  }
}

/**
 * Ouvre une fiche existante dans l'écran de validation.
 *
 * Le même écran sert à la création et à la correction : une seule mise en
 * page à tenir, et les mêmes règles s'appliquent des deux côtés. Seule
 * change la destination — `etat.enEdition` retient le nom du fichier, qui
 * sera réécrit tel quel au lieu d'en fabriquer un nouveau.
 */
function ouvrirEdition(nomFichier) {
  const fiche = (etat.collection ?? []).find((f) => f.nomFichier === nomFichier);
  if (!fiche) return;

  // Les mots-clés de la fiche sont tous actifs : ce sont ceux qu'on a déjà
  // choisis. Rien n'est « suggéré » ici, il n'y a pas eu d'enrichissement.
  const tags = (fiche.tags ?? []).map((t) => ({
    affichage: t,
    cle: normaliserTag(t),
    actif: true,
  }));

  majEtat({
    ecran: 'validation',
    fiche: { ...fiche },
    tags,
    enEdition: nomFichier,
    diagnostics: { mode: 'edition', sources: [], journal: [] },
    erreur: null,
    aSupprimer: null,
  });
}

async function retirerFiche(nomFichier) {
  const config = chargerConfig();
  const fiche = (etat.collection ?? []).find((f) => f.nomFichier === nomFichier);
  majEtat({ ecran: 'attente-suppression', erreur: null });
  try {
    await supprimerFiche({ nomFichier, message: `Retrait : ${fiche?.titre ?? nomFichier}` }, config);
    majEtat({
      ecran: 'collection',
      collection: (etat.collection ?? []).filter((f) => f.nomFichier !== nomFichier),
      aSupprimer: null,
      erreur: null,
    });
  } catch (err) {
    majEtat({
      ecran: 'collection',
      aSupprimer: null,
      erreur:
        err instanceof ErreurGitHub
          ? `Retrait impossible : ${err.message}`
          : 'Retrait impossible. Vérifiez votre connexion.',
    });
  }
}

// ── Écran : mots-clés (renommer, fusionner) ─────────────────────────────

/**
 * Inventaire des mots-clés de la collection, avec renommage global.
 *
 * Le besoin est né de l'usage : « bipolaire » et « troubles bipolaires »
 * désignent la même chose mais scindent le filtrage, et une majuscule mise
 * un jour et pas le lendemain suffit à créer un doublon. Corriger fiche par
 * fiche serait interminable.
 *
 * Renommer vers un mot-clé qui existe déjà les fusionne : c'est le même
 * geste, et c'est ce qu'on veut la plupart du temps.
 */
function vueMotsCles() {
  const inventaire = inventaireDesMotsCles();
  const enCours = etat.tagRenomme;

  const rangee = (entree) => {
    if (enCours === entree.tag) {
      const cible = etat.tagCible ?? entree.tag;
      const fusion = inventaire.find(
        (i) => i.tag !== entree.tag && normaliserTag(i.tag) === normaliserTag(cible),
      );
      return `
        <li class="mot-cle en-edition">
          <input type="text" value="${attr(cible)}" data-role="nouveau-nom"
                 list="mots-cles-connus" autocapitalize="off" aria-label="Nouveau nom" />
          ${fusion ? `<p class="aide">Fusionnera avec « ${texte(fusion.tag)} » (${fusion.n} fiche${fusion.n > 1 ? 's' : ''}).</p>` : ''}
          <div class="actions">
            <button type="button" class="principal" data-appliquer="${attr(entree.tag)}">
              Appliquer aux ${entree.n} fiche${entree.n > 1 ? 's' : ''}
            </button>
            <button type="button" class="lien-discret" data-annuler-renommage>Annuler</button>
          </div>
        </li>`;
    }
    if (etat.tagASupprimer === entree.tag) {
      return `
        <li class="mot-cle">
          <span class="mot-cle-nom">${texte(entree.tag)}</span>
          <div class="confirmation-suppression">
            <span>Retirer de ${entree.n} fiche${entree.n > 1 ? 's' : ''}&nbsp;?</span>
            <button type="button" class="danger" data-confirmer-tag="${attr(entree.tag)}">Oui</button>
            <button type="button" class="discret" data-annuler-suppression-tag>Non</button>
          </div>
        </li>`;
    }
    return `
      <li class="mot-cle">
        <button type="button" class="mot-cle-nom" data-renommer="${attr(entree.tag)}">
          ${texte(entree.tag)}
        </button>
        <span class="mot-cle-compte">${entree.n}</span>
        <button type="button" class="retirer" data-supprimer-tag="${attr(entree.tag)}"
                aria-label="Supprimer le mot-clé ${attr(entree.tag)}">×</button>
      </li>`;
  };

  return `
    <div class="ecran">
      <header class="entete">
        <button type="button" data-action="retour-collection" class="discret" aria-label="Retour">←</button>
        <h1>Mots-clés</h1>
        <span></span>
      </header>

      ${etat.erreur ? `<p class="erreur">${texte(etat.erreur)}</p>` : ''}
      ${etat.corrigee ? `<p class="succes">✓ ${texte(etat.corrigee)}</p>` : ''}

      <p class="aide">
        ${inventaire.length} mot${inventaire.length > 1 ? 's' : ''}-clé${inventaire.length > 1 ? 's' : ''}.
        Toucher un mot pour le renommer partout à la fois. Lui donner le nom
        d'un mot existant fusionne les deux.
      </p>

      <ul class="liste-mots-cles">${inventaire.map(rangee).join('')}</ul>
      <datalist id="mots-cles-connus"></datalist>
    </div>`;
}

/** Mots-clés de la collection chargée, avec leur nombre d'emplois. */
function inventaireDesMotsCles() {
  const comptes = new Map();
  for (const fiche of etat.collection ?? []) {
    for (const tag of fiche.tags ?? []) comptes.set(tag, (comptes.get(tag) ?? 0) + 1);
  }
  return [...comptes.entries()]
    .map(([tag, n]) => ({ tag, n }))
    .sort((a, b) => b.n - a.n || a.tag.localeCompare(b.tag, 'fr'));
}

/**
 * Applique un renommage à toutes les fiches concernées, en un seul commit.
 *
 * Un commit par fiche déclencherait autant de reconstructions du site — ce
 * qui a déjà épuisé le quota de l'hébergeur. `committerFichiers` n'en fait
 * qu'un, quel que soit le nombre de fiches touchées.
 */
async function appliquerRenommage(ancien, nouveau) {
  const config = chargerConfig();
  // Une cible vide vaut suppression : le mot-clé est retiré des fiches.
  const cible = (nouveau ?? '').trim();
  const suppression = cible === '';

  if (!suppression && cible === ancien) {
    majEtat({ tagRenomme: null, tagCible: null });
    return;
  }

  const touchees = (etat.collection ?? []).filter((f) => (f.tags ?? []).includes(ancien));
  if (!touchees.length) {
    majEtat({ tagRenomme: null, tagCible: null, erreur: 'Aucune fiche ne porte ce mot-clé.' });
    return;
  }

  majEtat({ ecran: 'attente-envoi', erreur: null });

  try {
    const misesAJour = touchees.map((fiche) => {
      // `dedupliquerTags` absorbe le cas de la fusion : si la fiche portait
      // déjà le mot-clé cible, il n'y apparaît pas deux fois.
      const tags = suppression
        ? (fiche.tags ?? []).filter((t) => t !== ancien)
        : dedupliquerTags((fiche.tags ?? []).map((t) => (t === ancien ? cible : t)));
      const modifiee = normaliserFiche({ ...fiche, tags });
      delete modifiee.nomFichier;
      delete modifiee.sha;
      return { fiche: modifiee, nomFichier: fiche.nomFichier };
    });

    const nb = `${touchees.length} fiche${touchees.length > 1 ? 's' : ''}`;
    await committerFichiers(
      {
        fichiers: misesAJour.map((m) => ({ chemin: `refs/${m.nomFichier}`, contenu: serialiser(m.fiche) })),
        message: suppression
          ? `Mot-clé « ${ancien} » retiré (${nb})`
          : `Mot-clé « ${ancien} » → « ${cible} » (${nb})`,
      },
      config,
    );

    // La collection en mémoire suit, pour que l'écran soit juste sans
    // relire tout le dépôt.
    const parNom = new Map(misesAJour.map((m) => [m.nomFichier, m.fiche]));
    majEtat({
      ecran: 'mots-cles',
      collection: (etat.collection ?? []).map((f) =>
        parNom.has(f.nomFichier) ? { ...parNom.get(f.nomFichier), nomFichier: f.nomFichier, sha: f.sha } : f,
      ),
      tagRenomme: null,
      tagCible: null,
      tagASupprimer: null,
      erreur: null,
      corrigee: suppression
        ? `« ${ancien} » retiré de ${nb}`
        : `« ${ancien} » → « ${cible} » sur ${nb}`,
    });
  } catch (err) {
    majEtat({
      ecran: 'mots-cles',
      tagRenomme: null,
      tagCible: null,
      erreur:
        err instanceof ErreurGitHub
          ? `Renommage impossible : ${err.message}`
          : 'Renommage impossible. Vérifiez votre connexion.',
    });
  }
}

// ── Écran : confirmation ────────────────────────────────────────────────

function vueConfirmation() {
  return `
    <div class="ecran ecran-centre">
      <p class="grosse-coche" aria-hidden="true">✓</p>
      <p>Fiche enregistrée.</p>
      <p class="aide">${texte(etat.fiche?.titre ?? '')}</p>
      <div class="actions actions-empilees">
        <button type="button" data-action="nouvelle" class="principal">Capturer une autre référence</button>
        <button type="button" data-action="collection" class="lien-discret">Voir la collection</button>
      </div>
    </div>`;
}

// ── Assemblage ───────────────────────────────────────────────────────────

/**
 * Recueille ce qui est tapé avant de redessiner l'écran.
 *
 * Ajouter un mot-clé reconstruit toute la page : tout ce qui n'existait que
 * dans le formulaire disparaissait alors. La case « garder cette fiche
 * entièrement privée » se décochait toute seule et le commentaire déjà écrit
 * s'effaçait, sans rien signaler — au point qu'une fiche voulue privée
 * pouvait finir publiée. L'état de la saisie est donc recopié dans `etat`
 * juste avant chaque redessin, et c'est lui qui est réaffiché.
 */
function recueillirSaisie() {
  const formulaire = $('[data-form="validation"]');
  if (!formulaire || !etat.fiche) return;
  const d = new FormData(formulaire);
  const texteDe = (nom) => (d.get(nom) ?? '').trim();
  etat.fiche = {
    ...etat.fiche,
    titre: texteDe('titre'),
    type: d.get('type') ?? etat.fiche.type,
    annee: texteDe('annee') ? Number(texteDe('annee')) : null,
    auteurs: texteDe('auteurs').split(',').map((a) => a.trim()).filter(Boolean),
    revue: texteDe('revue') || null,
    lien: texteDe('lien'),
    note: texteDe('note') || null,
    note_privee: texteDe('note_privee') || null,
    private: d.get('private') === 'on',
  };
}

function dessiner() {
  const racine = $('#racine');
  const config = chargerConfig();
  recueillirSaisie();

  if (!configValide(config) && etat.ecran !== 'attente-reglages') {
    etat.ecran = etat.ecran === 'reglages' ? 'reglages' : 'reglages';
  }

  const vues = {
    reglages: vueReglages,
    'attente-reglages': () => vueAttente('Vérification de l’accès au dépôt…'),
    saisie: vueSaisie,
    'attente-enrichissement': () => vueAttente('Recherche des informations…'),
    'attente-envoi': () => vueAttente('Enregistrement…'),
    'attente-collection': () => vueAttente('Lecture de la collection…'),
    'attente-suppression': () => vueAttente('Retrait…'),
    collection: vueCollection,
    'mots-cles': vueMotsCles,
    validation: vueValidation,
    confirmation: vueConfirmation,
  };

  racine.innerHTML = (vues[etat.ecran] ?? vueSaisie)();
  brancherEvenements(racine);
}

function brancherEvenements(racine) {
  $('[data-form="reglages"]', racine)?.addEventListener('submit', (ev) => {
    ev.preventDefault();
    soumettreReglages(new FormData(ev.target));
  });

  $('[data-form="saisie"]', racine)?.addEventListener('submit', (ev) => {
    ev.preventDefault();
    const saisie = new FormData(ev.target).get('saisie').trim();
    if (saisie) lancerEnrichissement(saisie);
  });

  $('[data-action="reglages"]', racine)?.addEventListener('click', () => majEtat({ ecran: 'reglages', erreur: null }));
  $('[data-action="collection"]', racine)?.addEventListener('click', () => ouvrirCollection());
  $('[data-action="retour"]', racine)?.addEventListener('click', () => majEtat({ ecran: 'saisie', erreur: null, aSupprimer: null }));

  // Le retrait se fait en deux temps : le « × » demande confirmation, et
  // seule la confirmation appelle GitHub. Sur un téléphone, un bouton
  // destructeur à un seul geste finit toujours par être touché par erreur.
  $$('[data-modifier]', racine).forEach((bouton) => {
    bouton.addEventListener('click', () => ouvrirEdition(bouton.dataset.modifier));
  });

  // ── Écran des mots-clés ──────────────────────────────────────────────
  $('[data-action="mots-cles"]', racine)?.addEventListener('click', () =>
    majEtat({ ecran: 'mots-cles', erreur: null, corrigee: null, tagRenomme: null, tagCible: null }),
  );
  $('[data-action="retour-collection"]', racine)?.addEventListener('click', () =>
    majEtat({ ecran: 'collection', erreur: null, corrigee: null, tagRenomme: null, tagCible: null }),
  );
  $$('[data-renommer]', racine).forEach((bouton) => {
    bouton.addEventListener('click', () =>
      majEtat({ tagRenomme: bouton.dataset.renommer, tagCible: bouton.dataset.renommer, corrigee: null }),
    );
  });
  $('[data-annuler-renommage]', racine)?.addEventListener('click', () =>
    majEtat({ tagRenomme: null, tagCible: null }),
  );

  const champNouveauNom = $('[data-role="nouveau-nom"]', racine);
  if (champNouveauNom) {
    remplirPropositions();
    champNouveauNom.focus();
    // On suit la saisie pour annoncer une fusion avant qu'elle n'ait lieu,
    // sans redessiner à chaque frappe — ce qui ferait perdre le curseur.
    let dernier = champNouveauNom.value;
    champNouveauNom.addEventListener('input', () => {
      const cible = champNouveauNom.value;
      const fusionneAvant = inventaireDesMotsCles().some(
        (i) => i.tag !== etat.tagRenomme && normaliserTag(i.tag) === normaliserTag(dernier),
      );
      const fusionneApres = inventaireDesMotsCles().some(
        (i) => i.tag !== etat.tagRenomme && normaliserTag(i.tag) === normaliserTag(cible),
      );
      dernier = cible;
      etat = { ...etat, tagCible: cible };
      if (fusionneAvant !== fusionneApres) dessiner();
    });
    champNouveauNom.addEventListener('keydown', (ev) => {
      if (ev.key !== 'Enter') return;
      ev.preventDefault();
      appliquerRenommage(etat.tagRenomme, champNouveauNom.value);
    });
  }

  $('[data-appliquer]', racine)?.addEventListener('click', (ev) => {
    const champ = $('[data-role="nouveau-nom"]', racine);
    appliquerRenommage(ev.currentTarget.dataset.appliquer, champ?.value ?? '');
  });

  // Suppression d'un mot-clé : en deux temps, comme celle d'une fiche.
  $$('[data-supprimer-tag]', racine).forEach((bouton) => {
    bouton.addEventListener('click', () =>
      majEtat({ tagASupprimer: bouton.dataset.supprimerTag, tagRenomme: null, corrigee: null }),
    );
  });
  $('[data-annuler-suppression-tag]', racine)?.addEventListener('click', () =>
    majEtat({ tagASupprimer: null }),
  );
  $('[data-confirmer-tag]', racine)?.addEventListener('click', (ev) =>
    // Une cible vide vaut suppression, le même chemin fait les deux.
    appliquerRenommage(ev.currentTarget.dataset.confirmerTag, ''),
  );
  $$('[data-supprimer]', racine).forEach((bouton) => {
    bouton.addEventListener('click', () => majEtat({ aSupprimer: bouton.dataset.supprimer }));
  });
  $('[data-annuler-suppression]', racine)?.addEventListener('click', () => majEtat({ aSupprimer: null }));
  $('[data-confirmer]', racine)?.addEventListener('click', (ev) => retirerFiche(ev.currentTarget.dataset.confirmer));
  // Annuler renvoie d'où l'on vient : à la collection si l'on corrigeait une
  // fiche, à la saisie si l'on en capturait une nouvelle.
  $('[data-action="annuler"]', racine)?.addEventListener('click', () => {
    if (etat.enEdition) {
      majEtat({ ecran: 'collection', fiche: null, enEdition: null, erreur: null });
    } else {
      majEtat({ ecran: 'saisie', fiche: null, erreur: null });
    }
  });
  $('[data-action="nouvelle"]', racine)?.addEventListener('click', () => majEtat({ ecran: 'saisie', saisie: '', fiche: null, erreur: null }));

  $('[data-action="manuel"]', racine)?.addEventListener('click', () => {
    majEtat({
      fiche: { type: 'ressource', titre: '', lien: '', tags: [], auteurs: [] },
      tags: [],
      diagnostics: { mode: 'manuel', sources: [] },
      ecran: 'validation',
      erreur: null,
    });
  });

  $('[data-action="pdf"]', racine)?.addEventListener('change', async (ev) => {
    const fichier = ev.target.files?.[0];
    if (fichier) lancerEnrichissementPdf(fichier);
  });

  $$('.puce', racine).forEach((bouton) => {
    bouton.addEventListener('click', () => {
      const i = Number(bouton.dataset.tagIndex);
      const tags = [...etat.tags];
      tags[i] = { ...tags[i], actif: !tags[i].actif };
      etat = { ...etat, tags };
      dessiner();
    });
  });

  const champTagLibre = $('[data-role="tag-libre"]', racine);
  if (champTagLibre) {
    remplirPropositions();

    const ajouterTag = (valeur) => {
      const cle = normaliserTag(valeur);
      if (!cle) return;
      const existant = etat.tags.find((t) => t.cle === cle);
      const tags = existant
        ? etat.tags.map((t) => (t.cle === cle ? { ...t, actif: true } : t))
        : [...etat.tags, { affichage: valeur.trim(), cle, actif: true }];
      etat = { ...etat, tags };
      champTagLibre.value = '';
      dessiner();
    };

    champTagLibre.addEventListener('keydown', (ev) => {
      if (ev.key !== 'Enter') return;
      // Sans cela, Entrée dans ce champ soumettrait le formulaire entier et
      // enregistrerait la fiche alors qu'on voulait seulement ajouter un mot.
      ev.preventDefault();
      if (champTagLibre.value.trim()) ajouterTag(champTagLibre.value);
    });

    $('[data-role="ajouter-tag"]', racine)?.addEventListener('click', () => {
      if (champTagLibre.value.trim()) ajouterTag(champTagLibre.value);
    });

    // Pas d'écoute de `change` ici : cet événement se déclenche aussi quand on
    // quitte le champ pour cliquer « Enregistrer ». La page se redessinait
    // alors sous le bouton, et l'enregistrement se perdait. Un mot-clé resté
    // dans le champ est repris à la soumission, voir `soumettreValidation`.

    // Signale les mots-clés déjà employés dont celui-ci n'est qu'une variante.
    // La liste native ne peut pas le faire : une fois « addictologie » tapé
    // en entier, plus aucune proposition ne correspond, alors que
    // « addiction » existe et désigne la même chose.
    const proches = $('[data-role="proches"]', racine);
    champTagLibre.addEventListener('input', () => {
      const candidats = motsClesProches(champTagLibre.value);
      if (!candidats.length) {
        proches.hidden = true;
        return;
      }
      proches.hidden = false;
      proches.innerHTML =
        'Déjà employé : ' +
        candidats
          .map((t) => `<button type="button" class="proche" data-proche="${attr(t)}">${texte(t)}</button>`)
          .join(' ');
      $$('[data-proche]', proches).forEach((b) => {
        b.addEventListener('click', () => ajouterTag(b.dataset.proche));
      });
    });
  }

  $('[data-form="validation"]', racine)?.addEventListener('submit', (ev) => {
    ev.preventDefault();
    soumettreValidation(new FormData(ev.target));
  });
}

// ── Enrichissement ───────────────────────────────────────────────────────

async function lancerEnrichissement(saisie, titreIndice = null) {
  const config = chargerConfig();
  majEtat({ ecran: 'attente-enrichissement', saisie, erreur: null });
  try {
    const resultat = await enrichir(saisie, {
      email: config?.email,
      traductions: traductionsMesh,
      tagsMax: 8,
      titreIndice,
    });
    accueillirResultat(resultat);
  } catch (err) {
    majEtat({ ecran: 'saisie', erreur: "La recherche a échoué. Vérifiez votre connexion et réessayez." });
  }
}

async function lancerEnrichissementPdf(fichier) {
  const config = chargerConfig();
  majEtat({ ecran: 'attente-enrichissement', erreur: null });
  try {
    const octets = new Uint8Array(await fichier.arrayBuffer());
    const { doi, texte: texteExtrait } = await extraireDoiPdf(octets);
    const resultat = doi
      ? await enrichir(doi, { email: config?.email, traductions: traductionsMesh, tagsMax: 8 })
      : await enrichirDepuisTexte(texteExtrait, { email: config?.email, traductions: traductionsMesh, tagsMax: 8 });
    accueillirResultat(resultat);
  } catch {
    majEtat({ ecran: 'saisie', erreur: "Lecture du PDF impossible. Essayez de coller le DOI directement." });
  }
}

function accueillirResultat(resultat) {
  const tags = [
    ...resultat.tags.suggeres.map((t) => ({ ...t, actif: true })),
    ...resultat.tags.complementaires.map((t) => ({ ...t, actif: false })),
  ];
  majEtat({ ecran: 'validation', fiche: resultat.fiche, tags, diagnostics: resultat.diagnostics, erreur: null });
}

// ── Enregistrement (écriture GitHub) ──────────────────────────────────

async function soumettreValidation(donnees) {
  const config = chargerConfig();

  const enEdition = etat.enEdition ?? null;

  const brut = {
    ...etat.fiche,
    titre: donnees.get('titre').trim(),
    type: donnees.get('type'),
    annee: donnees.get('annee') ? Number(donnees.get('annee')) : null,
    auteurs: donnees.get('auteurs').split(',').map((a) => a.trim()).filter(Boolean),
    revue: donnees.get('revue').trim() || null,
    lien: donnees.get('lien').trim(),
    note: donnees.get('note').trim() || null,
    note_privee: donnees.get('note_privee').trim() || null,
    private: donnees.get('private') === 'on',
    // Un mot-clé tapé mais non validé par « + » compte quand même : sinon il
    // disparaît sans un mot au moment d'enregistrer, ce qui ne se remarque
    // qu'après coup.
    tags: dedupliquerTags([
      ...etat.tags.filter((t) => t.actif).map((t) => t.affichage),
      ...analyserSaisieTags(donnees.get('tag-libre') ?? ''),
    ]),
  };

  // Le marqueur « à compléter » était posé par l'import faute de titre
  // exploitable. Dès qu'un humain a relu la fiche, il n'a plus de sens.
  if (enEdition) delete brut.a_completer;

  // Une référence sans identifiant reconnu par les sources n'est pas perdue :
  // elle est enregistrée telle quelle et reprise chaque jour par
  // `bin/completer.js`, qui la complétera dès que les bases auront rattrapé.
  //
  // C'est le cas courant quand on suit la bibliographie de près : un article
  // paru le matin n'arrive chez Crossref que plusieurs jours plus tard. Exiger
  // une saisie manuelle à ce moment-là reviendrait à faire payer à
  // l'utilisateur le retard des bases.
  if (brut.lien && !brut.doi && !brut.pmid) {
    brut.a_completer = true;
    if (!brut.titre) {
      const source = (() => {
        try { return new URL(brut.lien).hostname.replace(/^www\./, ''); } catch { return 'référence'; }
      })();
      brut.titre = `En attente de complétion — ${source}`;
      // Tenue hors du site tant qu'elle n'a pas de vrai titre : un intitulé
      // provisoire n'a rien à faire sur une page publique. Le marqueur
      // distingue ce masquage automatique d'un « privée » voulu, que la
      // complétion ne doit pas lever — sans quoi une fiche cochée privée
      // redeviendrait publique le jour où les bases la retrouvent.
      if (!brut.private) {
        brut.private = true;
        brut.prive_en_attente = true;
      }
    }
  }

  const fiche = normaliserFiche(brut);
  const problemes = validerFiche(fiche);
  if (!fiche.lien) {
    majEtat({ erreur: 'Le lien est obligatoire.' });
    return;
  }

  majEtat({ ecran: 'attente-envoi', erreur: null, avertissement: null });

  try {
    // En correction, la destination est connue : on réécrit le même fichier.
    // Chercher un doublon n'aurait pas de sens — la fiche est son propre
    // doublon — et changer son nom la ferait réapparaître comme nouvelle sur
    // le canal Telegram, qui n'annonce que les fichiers ajoutés.
    if (enEdition) {
      await ecrireFiche(
        { nomFichier: enEdition, contenu: serialiser(fiche), message: `Correction : ${fiche.titre}` },
        config,
      );

      // Retour direct à la liste, à jour, plutôt qu'à un écran proposant une
      // nouvelle capture : on corrige rarement une seule fiche, et repartir
      // de la saisie obligerait à rouvrir la collection à chaque fois.
      majEtat({
        ecran: 'collection',
        collection: (etat.collection ?? []).map((f) =>
          f.nomFichier === enEdition ? { ...fiche, nomFichier: enEdition } : f,
        ),
        fiche: null,
        enEdition: null,
        erreur: null,
        corrigee: fiche.titre,
      });
      return;
    }

    const existantes = await listerFiches(config);

    // Détection de doublon.
    //
    // Recapturer par erreur un article déjà lu est fréquent, et l'écraser en
    // silence effacerait le commentaire personnel déjà écrit dessus. La
    // comparaison se fait sur l'identité bibliographique — DOI, lien, titre —
    // et non sur le nom de fichier, qui ne dit rien d'un même article capturé
    // depuis deux adresses différentes.
    //
    // Il faut donc le contenu des fiches. C'est `lireFiches` qui le fournit,
    // exactement comme pour l'affichage de la collection : ce qui a déjà été lu
    // est servi depuis le cache par empreinte, et seul l'inconnu part sur le
    // réseau, par paquets de vingt. Le cas courant — une collection déjà
    // consultée sur cet appareil — ne coûte aucune requête.
    //
    // La version précédente lisait les fiches une par une, en série et sans
    // cache : une demi-minute d'attente à cent cinquante fiches, qui
    // s'allongeait à chaque référence ajoutée. Le délai empirait donc à mesure
    // que l'outil devenait utile.
    const cherchee = identite(fiche);
    const connues = await lireFiches(existantes, config);
    const jumelle = connues.find((f) => f.titre && identite(f) === cherchee);
    if (jumelle) {
      majEtat({
        ecran: 'validation',
        erreur: `Déjà en collection (« ${jumelle.titre} »). Modifiez le titre pour forcer une nouvelle fiche si c'est volontaire.`,
      });
      return;
    }

    // Nom distinct de la fonction `nomFichier` importée plus haut : une
    // variable locale du même nom la masquait dans toute la fonction, y compris
    // avant sa propre déclaration, et l'enregistrement échouait sans dire
    // pourquoi.
    const destination = nomFichierLibre(fiche, new Set(existantes.map((e) => e.name)));
    await ecrireFiche(
      { nomFichier: destination, contenu: serialiser(fiche), message: `Ajout : ${fiche.titre}` },
      config,
    );

    majEtat({ ecran: 'confirmation', fiche, erreur: null });
  } catch (err) {
    majEtat({
      ecran: 'validation',
      erreur:
        err instanceof ErreurGitHub
          ? `Échec de l'enregistrement : ${err.message}`
          : "Échec de l'enregistrement. Vérifiez votre connexion et réessayez.",
    });
  }
}

// ── Utilitaires d'échappement HTML ──────────────────────────────────────

const texte = (v) => String(v ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const attr = (v) => texte(v).replace(/"/g, '&quot;');

/**
 * Nettoie le titre d'onglet fourni par le navigateur.
 *
 * Les éditeurs y accolent leur nom (« … | The BMJ », « … - ScienceDirect »),
 * ce qui fausse la comparaison de titres faite par Crossref.
 */
function titreDePage(brut) {
  if (!brut) return null;
  const propre = String(brut)
    .split(/\s+[|–—]\s+|\s+-\s+(?=[A-Z][\w.]*$)/)[0]
    .trim();
  // En dessous de quelques mots, ce n'est pas un titre d'article mais un nom
  // de site : le passer à Crossref ne produirait que du bruit.
  return propre.split(/\s+/).length >= 5 ? propre : null;
}

/**
 * Démarrage par partage Android (`share_target` du manifeste) ou par le
 * favori de capture sur ordinateur — les deux passent par les mêmes
 * paramètres d'adresse.
 *
 * C'est ce qui règle le « en attendant » du §7 : une alerte de citation reçue
 * par mail se partage vers l'application, qui reçoit le lien ou le texte et
 * enchaîne directement sur l'enrichissement. Trois secondes, pas de
 * copier-coller.
 */
function demarrer() {
  // Le vocabulaire des mots-clés est chargé en tâche de fond : il alimente
  // les propositions de saisie, mais rien ne doit attendre après lui. Le
  // cache local prend le relais tant qu'il n'est pas arrivé.
  vocabulaire = vocabulaireEnCache();
  chargerVocabulaire();

  const params = new URLSearchParams(location.search);
  const partage = [params.get('url'), params.get('text'), params.get('title')].filter(Boolean).join(' ');

  if (partage && configValide(chargerConfig())) {
    // On nettoie l'URL pour qu'un rechargement ne relance pas la capture.
    history.replaceState(null, '', location.pathname);
    const analyse = analyserEntree(partage);
    etat.saisie = analyse.genre === 'inconnu' ? partage : (analyse.doi ?? analyse.pmid ?? analyse.url ?? partage);
    dessiner();
    // Le titre de la page sert de repli quand l'adresse ne livre aucun
    // identifiant : Crossref sait retrouver un article sur son titre exact.
    lancerEnrichissement(etat.saisie, titreDePage(params.get('title')));
    return;
  }

  dessiner();
}

/**
 * Y a-t-il quelque chose à perdre si la page se recharge maintenant ?
 *
 * Consulté par le rechargement automatique déclenché lors d'une mise à jour :
 * il vaut mieux une version périmée d'une minute qu'une fiche à moitié
 * remplie qui disparaît sous les doigts.
 */
window.veilleTravailEnCours = () =>
  etat.ecran === 'validation' || etat.ecran.startsWith('attente-');

demarrer();
