/**
 * Écriture d'une fiche dans le dépôt GitHub, depuis le navigateur (§3.1, V2
 * du cahier des charges : capturer depuis le téléphone sans serveur).
 *
 * L'API REST de GitHub sert `Access-Control-Allow-Origin: *` sur les
 * requêtes authentifiées, ce qui permet à une page statique (une PWA sur le
 * téléphone) d'écrire directement dans le dépôt sans passer par un serveur
 * intermédiaire. C'est ce qui tient la promesse « zéro serveur » du §3 pour
 * le cas d'usage mobile.
 *
 * Le jeton d'accès n'est jamais envoyé ailleurs qu'à `api.github.com` et
 * n'est jamais écrit dans le dépôt : il reste dans le `localStorage` du
 * navigateur qui l'a saisi (voir `web/app.js`).
 */

const RACINE = 'https://api.github.com';

class ErreurGitHub extends Error {
  constructor(message, statut) {
    super(message);
    this.name = 'ErreurGitHub';
    this.statut = statut;
  }
}

async function appel(chemin, config, options = {}) {
  const reponse = await fetch(`${RACINE}${chemin}`, {
    ...options,
    headers: {
      Accept: 'application/vnd.github+json',
      Authorization: `Bearer ${config.jeton}`,
      'X-GitHub-Api-Version': '2022-11-28',
      ...(options.body ? { 'Content-Type': 'application/json' } : {}),
      ...options.headers,
    },
  });
  if (!reponse.ok) {
    const corps = await reponse.json().catch(() => null);
    throw new ErreurGitHub(corps?.message ?? `HTTP ${reponse.status}`, reponse.status);
  }
  return reponse.status === 204 ? null : reponse.json();
}

/**
 * Encode une chaîne UTF-8 en base64.
 *
 * `btoa` seul corrompt les caractères accentués (il attend du Latin-1) :
 * indispensable ici puisque les fiches sont pleines de « é », « à », « œ ».
 */
function base64Utf8(texte) {
  const octets = new TextEncoder().encode(texte);
  let binaire = '';
  for (const octet of octets) binaire += String.fromCharCode(octet);
  return btoa(binaire);
}

/**
 * Le jeton peut-il écrire dans ce dépôt ? Vérification rapide avant de
 * lancer l'utilisateur dans une capture de quinze secondes qui échouerait à
 * la dernière étape.
 */
export async function verifierAcces(config) {
  let infos;
  try {
    infos = await appel(`/repos/${config.proprietaire}/${config.depot}`, config);
  } catch (err) {
    // GitHub répond « Not Found » aussi bien pour un dépôt qui n'existe pas
    // que pour un dépôt privé que le jeton n'a pas le droit de voir : il évite
    // ainsi de révéler l'existence de dépôts privés. Le message brut ne dit
    // donc rien d'exploitable, et une simple faute dans le nom du compte —
    // « aliamad » au lieu de « aliamad-lab » — laisse chercher longtemps.
    if (err instanceof ErreurGitHub && err.statut === 404) {
      throw new ErreurGitHub(
        `Dépôt « ${config.proprietaire}/${config.depot} » introuvable. Vérifier l'orthographe ` +
          `du compte et du dépôt, et que le jeton donne bien accès à ce dépôt-là.`,
        404,
      );
    }
    if (err instanceof ErreurGitHub && err.statut === 401) {
      throw new ErreurGitHub('Jeton invalide ou expiré.', 401);
    }
    throw err;
  }

  if (!infos.permissions?.push) {
    throw new ErreurGitHub(
      "Ce jeton n'a pas le droit d'écrire dans ce dépôt : lui donner la permission « Contents : Read and write ».",
      403,
    );
  }
  return { defaut: infos.default_branch };
}

/**
 * SHA du fichier s'il existe déjà à ce chemin sur la branche, sinon `null`.
 * L'API de contenu GitHub exige ce SHA pour modifier un fichier existant —
 * l'omettre revient à écraser sans contrôle de collision.
 */
async function shaExistant(config, chemin) {
  try {
    const info = await appel(
      `/repos/${config.proprietaire}/${config.depot}/contents/${encodeURIComponent(chemin)}` +
        `?ref=${encodeURIComponent(config.branche)}`,
      config,
    );
    return info.sha;
  } catch (err) {
    if (err instanceof ErreurGitHub && err.statut === 404) return null;
    throw err;
  }
}

/**
 * Liste les fiches déjà présentes dans `refs/` sur la branche configurée.
 *
 * Sert à deux choses avant l'écriture : détecter un doublon (même DOI déjà
 * capturé, cf. `identite()` dans `core/ref.js`) et choisir un nom de fichier
 * libre — exactement ce que fait la CLI via `core/store.js`, mais lu depuis
 * GitHub plutôt que depuis le disque.
 */
export async function listerFiches(config) {
  try {
    const entrees = await appel(
      `/repos/${config.proprietaire}/${config.depot}/contents/refs?ref=${encodeURIComponent(config.branche)}`,
      config,
    );
    return entrees.filter((e) => e.type === 'file' && /\.ya?ml$/.test(e.name));
  } catch (err) {
    // Dossier `refs/` pas encore créé : dépôt neuf, aucune fiche à comparer.
    if (err instanceof ErreurGitHub && err.statut === 404) return [];
    throw err;
  }
}

/** Contenu d'une fiche existante, pour comparer son identité (doublon). */
async function contenuFiche(config, nomFichier) {
  const info = await appel(
    `/repos/${config.proprietaire}/${config.depot}/contents/refs/${encodeURIComponent(nomFichier)}` +
      `?ref=${encodeURIComponent(config.branche)}`,
    config,
  );
  // L'API renvoie le contenu en base64, potentiellement coupé en lignes.
  const binaire = atob(info.content.replace(/\n/g, ''));
  const octets = Uint8Array.from(binaire, (c) => c.charCodeAt(0));
  return new TextDecoder('utf-8').decode(octets);
}

export { contenuFiche };

/**
 * Écrit une fiche dans `refs/<nom>.yaml` par un commit direct sur la
 * branche configurée (pas de pull request : la capture doit rester à un
 * seul geste, cf. contrainte des quinze secondes).
 */
export async function ecrireFiche({ nomFichier, contenu, message }, config) {
  const chemin = `refs/${nomFichier}`;
  const sha = await shaExistant(config, chemin);

  return appel(`/repos/${config.proprietaire}/${config.depot}/contents/${encodeURIComponent(chemin)}`, config, {
    method: 'PUT',
    body: JSON.stringify({
      message,
      content: base64Utf8(contenu),
      branch: config.branche,
      ...(sha ? { sha } : {}),
    }),
  });
}

/**
 * Écrit plusieurs fiches en un seul commit.
 *
 * L'API de contenu employée par `ecrireFiche` fabrique un commit par fichier.
 * Renommer un mot-clé porté par quinze fiches produirait donc quinze commits,
 * donc quinze reconstructions du site — ce qui épuise le quota de
 * l'hébergeur pour une seule correction.
 *
 * On passe donc par l'API Git : un objet par fichier, un arbre, un commit,
 * et la branche déplacée dessus. Quatre requêtes, quel que soit le nombre de
 * fiches touchées, et un seul commit dans l'historique.
 */
export async function committerFichiers({ fichiers, message }, config) {
  if (!fichiers.length) return null;
  const base = `/repos/${config.proprietaire}/${config.depot}`;

  // Sommet actuel de la branche : le commit qu'on va prolonger.
  const reference = await appel(`${base}/git/ref/heads/${encodeURIComponent(config.branche)}`, config);
  const commitParent = reference.object.sha;
  const commitDetail = await appel(`${base}/git/commits/${commitParent}`, config);

  // Un objet par contenu. GitHub les accepte en UTF-8 direct, ce qui évite
  // un encodage en base64 pour rien.
  const objets = await Promise.all(
    fichiers.map(async ({ chemin, contenu }) => {
      const objet = await appel(`${base}/git/blobs`, config, {
        method: 'POST',
        body: JSON.stringify({ content: contenu, encoding: 'utf-8' }),
      });
      return { path: chemin, mode: '100644', type: 'blob', sha: objet.sha };
    }),
  );

  // Arbre partiel : `base_tree` conserve tout ce qu'on ne touche pas.
  const arbre = await appel(`${base}/git/trees`, config, {
    method: 'POST',
    body: JSON.stringify({ base_tree: commitDetail.tree.sha, tree: objets }),
  });

  const commit = await appel(`${base}/git/commits`, config, {
    method: 'POST',
    body: JSON.stringify({ message, tree: arbre.sha, parents: [commitParent] }),
  });

  await appel(`${base}/git/refs/heads/${encodeURIComponent(config.branche)}`, config, {
    method: 'PATCH',
    body: JSON.stringify({ sha: commit.sha }),
  });

  return { sha: commit.sha, fichiers: fichiers.length };
}

/**
 * Supprime une fiche du dépôt.
 *
 * La suppression n'efface pas la référence de l'historique Git : le commit
 * qui l'avait ajoutée reste, et la fiche est récupérable. C'est un retrait de
 * la collection courante, pas une destruction — nuance qui compte pour
 * pouvoir supprimer sans crainte depuis un téléphone.
 *
 * Le SHA est exigé par l'API et sert de garde-fou : si la fiche a changé
 * entre l'affichage de la liste et le clic, GitHub refuse la suppression au
 * lieu d'effacer une version qu'on n'a pas vue.
 */
export async function supprimerFiche({ nomFichier, message }, config) {
  const chemin = `refs/${nomFichier}`;
  const sha = await shaExistant(config, chemin);
  if (!sha) throw new ErreurGitHub('Cette fiche n’existe plus dans le dépôt.', 404);

  return appel(`/repos/${config.proprietaire}/${config.depot}/contents/${encodeURIComponent(chemin)}`, config, {
    method: 'DELETE',
    body: JSON.stringify({ message, sha, branch: config.branche }),
  });
}

export { ErreurGitHub };
