/**
 * Crossref — métadonnées bibliographiques de référence (§3.3).
 *
 * C'est la source qui fait autorité sur titre, auteurs, revue, année, volume
 * et pages. PubMed est meilleur sur l'abstract et les MeSH, mais sa notion de
 * revue est un abrégé (« J Psychiatr Res ») là où Crossref donne le titre
 * complet, qui est ce qu'on veut afficher.
 */

import { getJSON } from './http.js';

const RACINE = 'https://api.crossref.org/works';

/**
 * Année de publication la plus fiable de l'enregistrement.
 *
 * Crossref expose jusqu'à trois dates. `issued` est la date officielle de
 * publication et doit primer ; les deux autres servent de repli pour les
 * articles parus en ligne avant leur numéro.
 */
function annee(oeuvre) {
  for (const cle of ['issued', 'published-print', 'published-online', 'created']) {
    const partie = oeuvre?.[cle]?.['date-parts']?.[0]?.[0];
    if (Number.isInteger(partie)) return partie;
  }
  return null;
}

function auteurs(oeuvre) {
  return (oeuvre?.author ?? [])
    .map((a) => {
      if (a.name) return a.name; // auteur collectif (consortium, groupe d'étude)
      return [a.given, a.family].filter(Boolean).join(' ').trim();
    })
    .filter(Boolean);
}

/** Crossref laisse parfois passer des entités HTML et des balises JATS. */
function nettoyer(valeur) {
  if (!valeur) return null;
  return String(valeur)
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim() || null;
}

/**
 * Le type Crossref traduit en type de fiche (§3.2).
 *
 * Tout ce qui n'est pas manifestement un article scientifique retombe sur
 * `ressource` : c'est plus honnête que d'étiqueter « article » un rapport ou
 * un chapitre, et le champ reste modifiable à la validation.
 */
function typeFiche(crossrefType) {
  const articles = new Set(['journal-article', 'proceedings-article', 'posted-content']);
  return articles.has(crossrefType) ? 'article' : 'ressource';
}

export async function chercherParDoi(doi, { email } = {}) {
  const url = new URL(`${RACINE}/${encodeURIComponent(doi)}`);
  if (email) url.searchParams.set('mailto', email);

  const donnees = await getJSON(url.toString());
  const oeuvre = donnees?.message;
  if (!oeuvre) return null;

  return {
    source: 'crossref',
    doi: (oeuvre.DOI ?? doi).toLowerCase(),
    titre: nettoyer(oeuvre.title?.[0]),
    sous_titre: nettoyer(oeuvre.subtitle?.[0]),
    auteurs: auteurs(oeuvre),
    revue: nettoyer(oeuvre['container-title']?.[0]),
    editeur: nettoyer(oeuvre.publisher),
    annee: annee(oeuvre),
    volume: oeuvre.volume ?? null,
    numero: oeuvre.issue ?? null,
    pages: oeuvre.page ?? null,
    type: typeFiche(oeuvre.type),
    type_crossref: oeuvre.type ?? null,
    // Crossref sert parfois un abstract en JATS ; on le garde en repli, mais
    // celui de PubMed est mieux découpé et sera préféré.
    abstract: nettoyer(oeuvre.abstract),
    licence_libre: (oeuvre.license ?? []).some((l) => /creativecommons/i.test(l.URL ?? '')),
  };
}

/**
 * DOI d'une œuvre à partir d'un identifiant d'éditeur (PII d'Elsevier).
 *
 * Les adresses ScienceDirect ne portent que le PII — `S2211364925000338` —
 * dont aucune règle ne permet de déduire le DOI. Mais Elsevier dépose ce PII
 * chez Crossref comme identifiant alternatif, et c'est interrogeable.
 * Sans cela, un dixième des références du canal Telegram resterait sans
 * métadonnées.
 */
export async function chercherParIdentifiantAlternatif(identifiant, { email } = {}) {
  const url = new URL(RACINE);
  url.searchParams.set('filter', `alternative-id:${identifiant}`);
  url.searchParams.set('rows', '1');
  url.searchParams.set('select', 'DOI');
  if (email) url.searchParams.set('mailto', email);

  const donnees = await getJSON(url.toString());
  return donnees?.message?.items?.[0]?.DOI?.toLowerCase() ?? null;
}

/** Titre réduit à ses mots significatifs, pour comparaison. */
function motsDuTitre(titre) {
  return new Set(
    String(titre ?? '')
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, ' ')
      .split(' ')
      .filter((mot) => mot.length > 2),
  );
}

/** Proportion de mots communs aux deux titres (indice de Dice, 0 à 1). */
function ressemblance(a, b) {
  const motsA = motsDuTitre(a);
  const motsB = motsDuTitre(b);
  if (!motsA.size || !motsB.size) return 0;
  let communs = 0;
  for (const mot of motsA) if (motsB.has(mot)) communs++;
  return (2 * communs) / (motsA.size + motsB.size);
}

/**
 * Recherche bibliographique par titre, pour rattraper une référence dont on
 * n'a pas le DOI (copiée depuis un PDF sans métadonnées, ou capturée depuis
 * la page d'un éditeur dont l'adresse ne contient pas le DOI).
 *
 * On compare les titres nous-mêmes plutôt que de suivre le classement de
 * Crossref, parce que ce classement est trompeur : sur un titre exact du BMJ,
 * le bon article ressort deuxième avec un score de 53, derrière un article
 * différent qui score 67. Prendre le premier résultat aurait rempli la fiche
 * avec le mauvais article, silencieusement — précisément l'erreur qu'une
 * saisie manuelle ne commet jamais.
 *
 * @param {number} options.ressemblanceMinimale part de mots communs exigée.
 *   0,85 laisse passer une ponctuation ou un sous-titre qui diffère, mais pas
 *   un article voisin sur le même sujet.
 */
export async function chercherParTitre(titre, { email, ressemblanceMinimale = 0.85 } = {}) {
  const url = new URL(RACINE);
  url.searchParams.set('query.bibliographic', titre);
  url.searchParams.set('rows', '5');
  url.searchParams.set('select', 'DOI,title,score');
  if (email) url.searchParams.set('mailto', email);

  const donnees = await getJSON(url.toString());
  const candidats = donnees?.message?.items ?? [];

  const evalues = candidats
    .map((item) => ({
      doi: item.DOI?.toLowerCase(),
      titre: nettoyer(item.title?.[0]),
      score: item.score,
      ressemblance: ressemblance(titre, item.title?.[0]),
    }))
    .filter((c) => c.doi && c.ressemblance >= ressemblanceMinimale)
    .sort((a, b) => b.ressemblance - a.ressemblance);

  return evalues[0] ?? null;
}
