/**
 * Unpaywall — lien en accès libre légal (§3.3, §3.7).
 *
 * Le cahier des charges exclut de publier des PDF. Ce connecteur est ce qui
 * rend cette contrainte tenable : plutôt que d'héberger un fichier, on
 * affiche le lien vers une version librement accessible quand il en existe
 * une, déposée par l'éditeur ou dans une archive institutionnelle.
 *
 * L'API est gratuite et sans compte ; elle exige seulement un email.
 */

import { getJSON, HttpError } from './http.js';

const RACINE = 'https://api.unpaywall.org/v2';

/**
 * Ordre de préférence des lieux d'hébergement.
 *
 * La version de l'éditeur est préférable (mise en page définitive,
 * pagination citable) ; un dépôt institutionnel héberge souvent le manuscrit
 * accepté, utile mais dont la pagination ne correspond pas.
 */
function rang(emplacement) {
  if (emplacement?.host_type === 'publisher') return 0;
  if (emplacement?.version === 'publishedVersion') return 1;
  return 2;
}

export async function chercherParDoi(doi, { email }) {
  if (!email) throw new Error('Unpaywall exige une adresse email (voir config/veille.config.yaml)');

  const url = new URL(`${RACINE}/${encodeURIComponent(doi)}`);
  url.searchParams.set('email', email);

  let donnees;
  try {
    donnees = await getJSON(url.toString());
  } catch (err) {
    // 404 = DOI inconnu d'Unpaywall. Ce n'est pas une panne, c'est une
    // réponse : il n'y a pas de version libre à proposer.
    if (err instanceof HttpError && err.status === 404) return { source: 'unpaywall', libre: false, url: null };
    throw err;
  }

  const emplacements = [donnees?.best_oa_location, ...(donnees?.oa_locations ?? [])]
    .filter(Boolean)
    .sort((a, b) => rang(a) - rang(b));

  const retenu = emplacements[0];
  return {
    source: 'unpaywall',
    libre: Boolean(donnees?.is_oa),
    // `url_for_pdf` pointe le fichier, `url` la page qui le porte. On préfère
    // la page : elle survit mieux aux réorganisations de site, et laisse le
    // lecteur voir le contexte plutôt que de déclencher un téléchargement.
    url: retenu?.url ?? retenu?.url_for_pdf ?? null,
    url_pdf: retenu?.url_for_pdf ?? null,
    hebergeur: retenu?.host_type ?? null,
    version: retenu?.version ?? null,
    licence: retenu?.license ?? null,
  };
}
