/**
 * OpenAlex — filet de sécurité et complément thématique (§3.3).
 *
 * Deux usages, tous deux en repli :
 *   1. Un abstract quand PubMed n'en a pas (revues non indexées MEDLINE,
 *      preprints, sciences humaines).
 *   2. Des concepts thématiques quand l'article n'a aucun MeSH — un preprint
 *      récent n'est indexé nulle part, mais il faut quand même proposer des
 *      tags à cocher, sans quoi l'écran de validation est vide.
 *
 * Les concepts OpenAlex sont produits par un modèle, pas par des indexeurs
 * humains : ils sont moins fiables que les MeSH et ne servent donc jamais
 * quand ces derniers existent.
 */

import { getJSON } from './http.js';

const RACINE = 'https://api.openalex.org/works';

/**
 * OpenAlex stocke les abstracts sous forme d'index inversé (chaque mot vers
 * la liste de ses positions) pour des raisons de droits. On reconstruit le
 * texte en replaçant chaque mot à ses positions.
 */
function reconstituerAbstract(index) {
  if (!index || typeof index !== 'object') return null;
  const mots = [];
  for (const [mot, positions] of Object.entries(index)) {
    for (const position of positions) mots[position] = mot;
  }
  const texte = mots.filter((m) => m !== undefined).join(' ').trim();
  return texte || null;
}

export async function chercherParDoi(doi, { email, seuilConcept = 0.4 } = {}) {
  const url = new URL(`${RACINE}/doi:${encodeURIComponent(doi)}`);
  if (email) url.searchParams.set('mailto', email);

  const oeuvre = await getJSON(url.toString());
  if (!oeuvre?.id) return null;

  return {
    source: 'openalex',
    titre: oeuvre.title ?? null,
    annee: oeuvre.publication_year ?? null,
    revue: oeuvre.primary_location?.source?.display_name ?? null,
    abstract: reconstituerAbstract(oeuvre.abstract_inverted_index),
    libre: Boolean(oeuvre.open_access?.is_oa),
    url_libre: oeuvre.open_access?.oa_url ?? null,
    // Le score est une probabilité ; en dessous de 0,4 les concepts partent
    // dans des généralités (« Psychology », « Medicine ») sans valeur de tri.
    concepts: (oeuvre.concepts ?? [])
      .filter((c) => (c.score ?? 0) >= seuilConcept && (c.level ?? 0) >= 1)
      .map((c) => ({ terme: c.display_name, score: c.score, niveau: c.level })),
    type_openalex: oeuvre.type ?? null,
  };
}
