/**
 * Couche HTTP commune à tous les connecteurs.
 *
 * Volontairement construite sur `fetch` global et rien d'autre : le même
 * fichier tourne sous Node 20+ et dans le navigateur, ce qui permet à
 * l'interface web de validation de réutiliser tel quel le moteur
 * d'enrichissement sans serveur intermédiaire.
 *
 * Les quatre API interrogées (Crossref, NCBI E-utilities, Unpaywall,
 * OpenAlex) renvoient toutes `Access-Control-Allow-Origin: *`, elles sont
 * donc appelables directement depuis une page statique.
 */

const UA = 'veille/1.0 (outil personnel de veille bibliographique)';

/**
 * En-têtes envoyés avec chaque requête.
 *
 * L'identification `User-Agent` n'est envoyée que hors navigateur. Dans une
 * page, elle n'est pas un en-tête « simple » : Firefox la transmet, ce qui
 * déclenche une demande d'autorisation préalable (CORS) qu'aucune des quatre
 * API n'accepte pour cet en-tête. Toutes les recherches échouaient alors, et
 * la fiche arrivait vide quel que soit l'article. Chrome, lui, l'ignore en
 * silence — d'où une panne propre à Firefox, invisible dans les autres
 * navigateurs. Dans le navigateur, l'adresse email passée en paramètre
 * suffit à s'identifier auprès de Crossref et d'Unpaywall.
 */
export function entetes(accept, dansNavigateur = typeof document !== 'undefined') {
  return dansNavigateur ? { Accept: accept } : { Accept: accept, 'User-Agent': UA };
}

/** Erreur portant le code HTTP, pour distinguer « absent » de « en panne ». */
export class HttpError extends Error {
  constructor(status, url) {
    super(`HTTP ${status} sur ${url}`);
    this.name = 'HttpError';
    this.status = status;
    this.url = url;
  }
}

const dormir = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * Un code HTTP mérite-t-il une relance ?
 *
 * 429 en fait partie, et ce n'est pas un détail : les E-utilities du NCBI
 * plafonnent à trois requêtes par seconde, seuil franchi dès qu'on capture
 * deux références coup sur coup. Sans relance, la deuxième capture rend une
 * fiche vide — un échec silencieux et intermittent, le pire genre.
 *
 * 404 en revanche est une réponse et non une panne : ce DOI est inconnu de ce
 * fournisseur, réessayer ne changera rien.
 */
const relancable = (statut) => statut === 429 || statut === 408 || statut >= 500;

/**
 * `fetch` avec délai maximal, en-tête d'identification et relances mesurées.
 *
 * Trois tentatives au plus, temporisation croissante, et respect de l'en-tête
 * `Retry-After` quand le serveur le fournit. Au-delà on rend la main : faire
 * patienter devant un écran de validation qui ne vient pas coûte plus cher
 * qu'un champ à compléter soi-même.
 */
export async function request(url, { timeout = 10000, accept = 'application/json', tentatives = 3 } = {}) {
  let derniere = null;

  for (let tentative = 0; tentative < tentatives; tentative++) {
    if (tentative > 0) await dormir(derniere?.attendre ?? 400 * 2 ** (tentative - 1));

    const abort = new AbortController();
    const minuterie = setTimeout(() => abort.abort(), timeout);
    try {
      const reponse = await fetch(url, {
        signal: abort.signal,
        headers: entetes(accept),
      });
      if (reponse.ok) return reponse;

      if (!relancable(reponse.status)) throw new HttpError(reponse.status, url);

      // `Retry-After` est exprimé en secondes ; le serveur sait mieux que
      // nous combien de temps il faut le laisser tranquille.
      const indication = Number(reponse.headers.get('retry-after'));
      derniere = {
        erreur: new HttpError(reponse.status, url),
        attendre: Number.isFinite(indication) && indication > 0 ? Math.min(indication * 1000, 5000) : null,
      };
    } catch (err) {
      // Un HttpError qui remonte ici a déjà été jugé non relançable.
      if (err instanceof HttpError) throw err;
      derniere = { erreur: err, attendre: null };
    } finally {
      clearTimeout(minuterie);
    }
  }

  throw derniere?.erreur ?? new Error(`Échec inattendu sur ${url}`);
}

export async function getJSON(url, options) {
  const reponse = await request(url, options);
  return reponse.json();
}

export async function getText(url, options) {
  const reponse = await request(url, { accept: 'text/plain, */*', ...options });
  return reponse.text();
}

/**
 * Exécute plusieurs enrichissements sans qu'un fournisseur en panne ne fasse
 * tomber les autres. Renvoie `null` à la place du résultat manquant.
 *
 * C'est le comportement voulu : une fiche sans abstract reste une fiche
 * valable, alors qu'une capture qui échoue est une capture qu'on ne refera
 * pas.
 */
export async function tolerant(promesse, etiquette, journal = []) {
  try {
    return await promesse;
  } catch (err) {
    journal.push({ source: etiquette, message: err.message });
    return null;
  }
}
