/**
 * Extraction du DOI d'un PDF (§3.3), sans dépendance et sans moteur de rendu.
 *
 * Le pari : on ne cherche pas à *lire* le PDF, seulement à y trouver un DOI.
 * C'est un problème beaucoup plus simple que l'extraction de texte, et il se
 * résout sans embarquer pdf.js — donc le même fichier tourne dans Node et
 * dans le navigateur, où l'interface de validation acceptera un PDF déposé.
 *
 * Trois passes, de la moins chère à la plus chère :
 *   1. les métadonnées XMP, presque toujours en clair dans le fichier ;
 *   2. le texte non compressé (annotations, liens hypertexte) ;
 *   3. les flux compressés, décompressés puis fouillés.
 *
 * En cas d'échec, on rend `null` et l'appelant bascule sur la saisie
 * manuelle. Un PDF sans DOI trouvable existe (scan, document associatif) et
 * ce n'est pas une anomalie.
 */

import { extraireDois } from './doi.js';

/** Octets → chaîne latin-1, qui préserve la valeur de chaque octet. */
function enTexte(octets) {
  let sortie = '';
  const pas = 0x8000; // par tranches, sinon String.fromCharCode déborde la pile
  for (let i = 0; i < octets.length; i += pas) {
    sortie += String.fromCharCode.apply(null, octets.subarray(i, i + pas));
  }
  return sortie;
}

/** Décompression zlib, via l'API disponible dans l'environnement courant. */
async function inflater(octets) {
  if (typeof DecompressionStream === 'function') {
    const flux = new Blob([octets]).stream().pipeThrough(new DecompressionStream('deflate'));
    return new Uint8Array(await new Response(flux).arrayBuffer());
  }
  const { inflateSync } = await import('node:zlib');
  return new Uint8Array(inflateSync(octets));
}

/**
 * DOI déclaré dans les métadonnées XMP.
 *
 * C'est la passe la plus fiable : Elsevier, Wiley, Springer et Nature y
 * inscrivent le DOI, et ce bloc XML n'est pas compressé.
 */
function depuisXmp(texte) {
  const motifs = [
    /<prism:doi>\s*([^<]+)<\/prism:doi>/i,
    /<dc:identifier[^>]*>\s*(?:doi:)?\s*([^<]+)<\/dc:identifier>/i,
    /\/doi\s*\(\s*([^)]+)\)/i, // dictionnaire Info, syntaxe PDF native
    /xmp:doi\s*=\s*"([^"]+)"/i,
  ];
  for (const motif of motifs) {
    const trouve = motif.exec(texte);
    const dois = extraireDois(trouve?.[1]);
    if (dois.length) return dois[0];
  }
  return null;
}

/** Découpe les flux `stream ... endstream` du fichier. */
function* flux(texte) {
  const debutMotif = /stream\r?\n?/g;
  let trouve;
  while ((trouve = debutMotif.exec(texte)) !== null) {
    const debut = trouve.index + trouve[0].length;
    const fin = texte.indexOf('endstream', debut);
    if (fin === -1) continue;
    // Les très gros flux sont des images ; les fouiller coûte cher et ne
    // rapporte rien, le DOI est dans le texte.
    if (fin - debut > 2_000_000) continue;
    yield [debut, fin];
  }
}

/**
 * Cherche un DOI dans le PDF.
 *
 * @param {Uint8Array|ArrayBuffer} donnees
 * @returns {Promise<{doi: string|null, passe: string, texte: string}>}
 *   `texte` porte ce qui a pu être lu, utilisé en repli pour la recherche
 *   Crossref par titre.
 */
export async function extraireDoiPdf(donnees) {
  const octets = donnees instanceof Uint8Array ? donnees : new Uint8Array(donnees);
  const brut = enTexte(octets);

  const xmp = depuisXmp(brut);
  if (xmp) return { doi: xmp, passe: 'métadonnées XMP', texte: '' };

  const enClair = extraireDois(brut);
  if (enClair.length) return { doi: enClair[0], passe: 'texte non compressé', texte: '' };

  // Passe 3 : on décompresse. Le premier flux qui livre un DOI gagne — c'est
  // en général la première page, où figure l'en-tête de l'éditeur.
  let texteDecompresse = '';
  for (const [debut, fin] of flux(brut)) {
    let clair;
    try {
      clair = enTexte(await inflater(octets.subarray(debut, fin)));
    } catch {
      continue; // flux non compressé ou chiffré : sans intérêt ici
    }
    // Le texte d'un PDF est éclaté en fragments `(...)Tj` ; on les recolle,
    // sans quoi un DOI coupé en deux échappe à l'expression régulière.
    const lisible = clair.replace(/\\([()\\])/g, '$1').replace(/\)\s*-?\d*\s*\(/g, '');
    const dois = extraireDois(lisible);
    if (dois.length) return { doi: dois[0], passe: 'flux compressé', texte: lisible };
    if (texteDecompresse.length < 20_000) texteDecompresse += `${lisible}\n`;
  }

  return { doi: null, passe: 'aucune', texte: texteDecompresse };
}
