/**
 * Fabrication des tags proposés à la validation (§3.3).
 *
 * Principe : les tags viennent d'un vocabulaire déjà normalisé par des
 * humains — les descripteurs MeSH — plutôt que d'une invention libre à
 * chaque capture. C'est ce qui empêche la collection de dériver vers
 * « catatonie », « catatonia » et « Catatonie » comme trois tags distincts.
 *
 * Deux formes coexistent volontairement pour chaque tag :
 *   - la forme d'affichage, accentuée et lisible (« épidémiologie ») ;
 *   - la clé de comparaison, sans accent ni ponctuation (« epidemiologie »),
 *     utilisée pour dédoublonner, filtrer et construire les URL.
 * Sans cette séparation, il faut choisir entre des tags laids et des
 * doublons invisibles à l'œil.
 */

/**
 * Descripteurs MeSH systématiquement écartés.
 *
 * Ce sont les « check tags » : MEDLINE les appose sur presque tout article
 * concerné, si bien qu'ils ne discriminent rien. « Humans » sur une fiche de
 * psychiatrie n'apprend rien et occupe une place dans les huit tags proposés.
 */
const ECARTES = new Set(
  [
    'Humans', 'Animals', 'Male', 'Female', 'Adult', 'Aged', 'Aged, 80 and over',
    'Middle Aged', 'Young Adult', 'Adolescent', 'Child', 'Child, Preschool',
    'Infant', 'Infant, Newborn', 'Pregnancy', 'Rats', 'Mice',
    'History, 20th Century', 'History, 21st Century', 'History, 19th Century',
    'Reproducibility of Results', 'Surveys and Questionnaires',
  ].map((t) => t.toLowerCase()),
);

/**
 * Clé de comparaison : minuscules, sans diacritiques, ponctuation en tirets.
 *
 * Sert à dédoublonner et à construire les URL de filtrage. Ne jamais
 * l'afficher — c'est la forme accentuée qui va à l'écran.
 */
export function normaliserTag(brut) {
  return String(brut ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // diacritiques isolés par NFD
    .toLowerCase()
    .replace(/['’]/g, '-')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/**
 * Remet à l'endroit les descripteurs MeSH inversés.
 *
 * MeSH classe alphabétiquement en inversant : « Schizophrenia, Paranoid »
 * plutôt que « Paranoid Schizophrenia ». Utile dans un index imprimé,
 * illisible comme tag.
 */
function desinverser(terme) {
  const parties = terme.split(',').map((p) => p.trim()).filter(Boolean);
  if (parties.length !== 2) return terme;
  // On n'inverse pas les qualificatifs numériques (« Infant, Newborn » passe,
  // « Trisomy 21 » n'est pas concerné) ni ce qui commence par une minuscule.
  if (/^\d/.test(parties[1])) return terme;
  return `${parties[1]} ${parties[0]}`;
}

/** Applique la table de traduction, sinon désinverse et slugifie l'anglais. */
function enTag(terme, traductions) {
  const cle = terme.trim().toLowerCase();
  const traduit = traductions?.[cle];
  if (traduit) return { affichage: traduit, cle: normaliserTag(traduit), traduit: true };
  const anglais = desinverser(terme);
  return { affichage: normaliserTag(anglais), cle: normaliserTag(anglais), traduit: false };
}

/**
 * Construit la liste de tags à cocher sur l'écran de validation.
 *
 * L'ordre compte plus qu'il n'y paraît : ce qui est en tête sera coché sans
 * réfléchir, ce qui est en queue ne le sera jamais. On classe donc par force
 * du signal — MeSH majeurs, puis MeSH mineurs, puis concepts OpenAlex — et
 * on tronque, plutôt que de tout proposer et de laisser trier l'humain.
 *
 * @param {object} sources
 * @param {Array<{terme:string,majeur:boolean}>} [sources.mesh]
 * @param {Array<{terme:string,score:number}>}   [sources.concepts]
 * @param {Record<string,string>}                [sources.traductions]
 * @param {number}                               [sources.max]
 */
export function suggererTags({ mesh = [], concepts = [], traductions = {}, max = 8 } = {}) {
  const retenus = new Map(); // clé → { affichage, cle, origine, majeur }

  const ajouter = (terme, origine, majeur) => {
    if (!terme) return;
    if (ECARTES.has(terme.trim().toLowerCase())) return;
    const tag = enTag(terme, traductions);
    if (!tag.cle || tag.cle.length < 2) return;
    // Premier arrivé, premier servi : un terme vu comme MeSH majeur ne doit
    // pas être rétrogradé par sa réapparition comme concept OpenAlex.
    if (retenus.has(tag.cle)) return;
    retenus.set(tag.cle, { ...tag, origine, majeur, terme_source: terme });
  };

  for (const entree of mesh.filter((m) => m.majeur)) ajouter(entree.terme, 'mesh', true);
  for (const entree of mesh.filter((m) => !m.majeur)) ajouter(entree.terme, 'mesh', false);
  // Les concepts OpenAlex ne comblent que le vide laissé par les MeSH.
  if (retenus.size < max) {
    for (const entree of concepts) ajouter(entree.terme, 'openalex', false);
  }

  const liste = [...retenus.values()];
  return {
    // Pré-cochés : les sujets centraux de l'article. C'est ce qui permet à la
    // validation de tenir en quinze secondes — on décoche l'exception, on ne
    // coche pas la règle.
    suggeres: liste.filter((t) => t.majeur).slice(0, max),
    complementaires: liste.filter((t) => !t.majeur).slice(0, Math.max(0, max - liste.filter((t) => t.majeur).length) + max),
    // Termes qui n'ont pas de traduction : signalés pour enrichir
    // config/mesh-fr.yaml au fil de l'eau plutôt qu'en une corvée initiale.
    non_traduits: liste.filter((t) => !t.traduit && t.origine === 'mesh').map((t) => t.terme_source),
  };
}

/** Nettoie une saisie manuelle de tags (« a, b , c » → ['a','b','c']). */
export function analyserSaisieTags(saisie) {
  return String(saisie ?? '')
    .split(/[,;]/)
    .map((t) => t.trim())
    .filter(Boolean);
}

/** Déduplique une liste de tags sur la clé normalisée, en gardant l'ordre. */
export function dedupliquerTags(tags) {
  const vus = new Set();
  const sortie = [];
  for (const tag of tags) {
    const cle = normaliserTag(tag);
    if (!cle || vus.has(cle)) continue;
    vus.add(cle);
    sortie.push(tag.trim());
  }
  return sortie;
}
