/**
 * Le modèle de fiche et sa sérialisation (§3.1, §3.2).
 *
 * La source de vérité est un fichier YAML par référence. Tout ce qui compte
 * ici est qu'un être humain puisse ouvrir ce fichier dans dix ans, avec
 * n'importe quel éditeur de texte, et comprendre son contenu sans
 * documentation. D'où : des clés en français, aucune indirection, aucun
 * identifiant technique, et l'ordre des champs choisi pour la lecture et non
 * pour la machine.
 */

import YAML from 'yaml';
import { normaliserTag, dedupliquerTags } from './tags.js';
import { urlDoi, urlPubmed } from './doi.js';

/** Valeurs autorisées du champ `type` (§3.2). */
export const TYPES = ['article', 'ressource', 'guide', 'evenement'];

/** Libellé affiché en petites capitales à côté du titre, pour les non-articles. */
export const LIBELLES_TYPE = {
  article: null, // cas par défaut : aucun marqueur, il serait sur toutes les fiches
  ressource: 'Ressource',
  guide: 'Guide',
  evenement: 'Événement',
};

/**
 * Ordre d'écriture des clés dans le fichier.
 *
 * Les quatre champs toujours présents en tête, puis l'identification, puis
 * la description bibliographique, puis ce que j'ajoute moi. Un `git diff` sur
 * une fiche reste ainsi lisible.
 */
const ORDRE = [
  'titre', 'type', 'lien', 'tags',
  'doi', 'pmid', 'pmcid',
  'auteurs', 'revue', 'annee', 'volume', 'numero', 'pages',
  'abstract',
  'note', 'note_privee', 'private',
  'lien_libre', 'pdf_local',
  'ajoute_le', 'sources',
];

const MOTS_VIDES = new Set([
  'a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in', 'is', 'of', 'on', 'or',
  'the', 'to', 'with', 'le', 'la', 'les', 'de', 'des', 'du', 'et', 'un', 'une',
  'dans', 'sur', 'pour', 'chez', 'aux',
]);

const sansAccents = (t) =>
  String(t ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');

/** Nom de famille du premier auteur, réduit à sa forme sûre pour un chemin. */
function cleAuteur(auteurs) {
  const premier = auteurs?.[0];
  if (!premier) return 'anonyme';
  // « Marie-Odile Krebs » → « krebs » ; on prend le dernier mot, qui est le
  // nom de famille dans la forme « Prénom Nom » que produisent nos sources.
  const mots = sansAccents(premier).trim().split(/\s+/);
  const nom = mots.at(-1) ?? premier;
  return nom.toLowerCase().replace(/[^a-z0-9]+/g, '') || 'anonyme';
}

/** Premier mot porteur de sens du titre, pour rendre le nom de fichier parlant. */
function cleTitre(titre) {
  const mots = sansAccents(titre)
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, ' ')
    .split(/\s+/)
    .filter((m) => m.length > 2 && !MOTS_VIDES.has(m));
  return (mots[0] ?? 'sans-titre').slice(0, 24);
}

/**
 * Nom de fichier d'une fiche : `2024-smith-catatonia.yaml`.
 *
 * Trié chronologiquement dans un `ls`, identifiable à l'œil, et stable :
 * recalculer le nom sur la même fiche redonne le même résultat, ce qui évite
 * qu'une correction de tag ne déplace le fichier dans l'historique Git.
 */
export function nomFichier(fiche) {
  const annee = fiche.annee ?? 'sd'; // « sans date »
  return `${annee}-${cleAuteur(fiche.auteurs)}-${cleTitre(fiche.titre)}.yaml`;
}

/** Ajoute un suffixe numérique tant que le nom est déjà pris. */
export function nomFichierLibre(fiche, existants) {
  const base = nomFichier(fiche).replace(/\.yaml$/, '');
  if (!existants.has(`${base}.yaml`)) return `${base}.yaml`;
  for (let n = 2; n < 100; n++) {
    if (!existants.has(`${base}-${n}.yaml`)) return `${base}-${n}.yaml`;
  }
  return `${base}-${Date.now()}.yaml`;
}

/**
 * Normalise une fiche : valeurs par défaut, types corrigés, champs vides
 * retirés.
 *
 * Retirer les champs vides est délibéré : une fiche d'événement ne doit pas
 * porter `revue: null`, `doi: null`, `volume: null`. Le fichier doit décrire
 * ce qui existe, pas le formulaire qu'on n'a pas rempli.
 */
export function normaliserFiche(brut) {
  const fiche = { ...brut };

  fiche.type = TYPES.includes(fiche.type) ? fiche.type : 'article';
  fiche.titre = String(fiche.titre ?? '').trim();
  fiche.tags = dedupliquerTags(Array.isArray(fiche.tags) ? fiche.tags : []);
  fiche.auteurs = (Array.isArray(fiche.auteurs) ? fiche.auteurs : []).map((a) => String(a).trim()).filter(Boolean);

  if (fiche.doi) fiche.doi = String(fiche.doi).toLowerCase();
  if (fiche.annee != null) fiche.annee = Number(fiche.annee) || null;
  fiche.private = fiche.private === true;

  // Le lien est obligatoire (§3.2) : à défaut de lien saisi, on le déduit du
  // premier identifiant disponible. Une fiche sans lien serait une impasse.
  fiche.lien = fiche.lien || urlDoi(fiche.doi) || urlPubmed(fiche.pmid) || fiche.lien_libre || '';

  fiche.ajoute_le = fiche.ajoute_le ?? new Date().toISOString().slice(0, 10);

  for (const [cle, valeur] of Object.entries(fiche)) {
    const vide =
      valeur == null ||
      valeur === '' ||
      (Array.isArray(valeur) && valeur.length === 0) ||
      (cle === 'private' && valeur === false);
    if (vide) delete fiche[cle];
  }
  return fiche;
}

/** Défauts de la fiche, dans l'ordre de gravité. Liste vide = fiche valide. */
export function validerFiche(fiche) {
  const problemes = [];
  if (!fiche.titre) problemes.push('titre manquant');
  if (!fiche.lien) problemes.push('lien manquant');
  if (!TYPES.includes(fiche.type)) problemes.push(`type inconnu : ${fiche.type}`);
  if (!Array.isArray(fiche.tags) || fiche.tags.length === 0) {
    // Volontairement un avertissement et non une erreur : une fiche sans tag
    // reste retrouvable par la recherche plein texte (§3.6).
    problemes.push('aucun tag — la fiche ne remontera que par la recherche plein texte');
  }
  return problemes;
}

/** Fiche → texte YAML, avec un en-tête de repérage. */
export function serialiser(fiche) {
  const ordonnee = {};
  for (const cle of ORDRE) if (cle in fiche) ordonnee[cle] = fiche[cle];
  for (const cle of Object.keys(fiche)) if (!(cle in ordonnee)) ordonnee[cle] = fiche[cle];

  const corps = YAML.stringify(ordonnee, {
    lineWidth: 0,        // pas de repli automatique : les diffs restent lisibles
    defaultStringType: 'PLAIN',
    defaultKeyType: 'PLAIN',
    blockQuote: 'literal', // abstract et notes en bloc `|`, agréables à relire
  });
  return `# Fiche de veille — modifiable à la main, c'est le format de référence.\n${corps}`;
}

/** Texte YAML → fiche normalisée. */
export function deserialiser(texte) {
  const donnees = YAML.parse(texte) ?? {};
  return normaliserFiche(donnees);
}

/** Fiche → clé d'identité, pour détecter les doublons avant écriture. */
export function identite(fiche) {
  if (fiche.doi) return `doi:${fiche.doi}`;
  if (fiche.pmid) return `pmid:${fiche.pmid}`;
  if (fiche.lien) return `url:${String(fiche.lien).replace(/\/+$/, '').toLowerCase()}`;
  return `titre:${normaliserTag(fiche.titre)}`;
}
