/**
 * Orchestration de l'enrichissement — le cœur de la porte d'entrée unique
 * (§3.3).
 *
 * Contrat de ce module, à préserver : il ne connaît ni le terminal, ni le
 * système de fichiers, ni le DOM. On lui donne une chaîne (DOI, URL, PMID) ou
 * le texte d'un PDF, il rend un brouillon de fiche. C'est ce qui permet à la
 * CLI, à l'interface web de validation et à la future GitHub Action du §7 de
 * partager le même moteur sans le dupliquer.
 */

import { analyserEntree, urlDoi, urlPubmed, extraireDois, piiDepuisUrl, normaliserDoi } from './doi.js';
import { tolerant } from './http.js';
import * as crossref from './crossref.js';
import * as pubmed from './pubmed.js';
import * as unpaywall from './unpaywall.js';
import * as openalex from './openalex.js';
import { suggererTags } from './tags.js';

/**
 * Première valeur non vide parmi les candidats, dans l'ordre donné.
 * L'ordre encode quelle source fait autorité sur quel champ.
 */
const premier = (...candidats) =>
  candidats.find((v) => v != null && v !== '' && !(Array.isArray(v) && v.length === 0)) ?? null;

/**
 * Résout les identifiants croisés à partir de ce qu'on tient.
 *
 * PubMed sait donner le DOI d'un PMID, et inversement. Une seule requête
 * d'aiguillage suffit à ouvrir les trois autres sources en parallèle.
 */
async function resoudreIdentifiants(entree, journal) {
  let { doi, pmid, pmcid } = entree;

  if (!doi && pmid) {
    const notice = await tolerant(pubmed.chercherParPmid(pmid), 'pubmed (résolution)', journal);
    doi = notice?.doi ?? null;
    pmcid = pmcid ?? notice?.pmcid ?? null;
  } else if (doi && !pmid) {
    pmid = await tolerant(pubmed.trouverPmid({ doi }), 'pubmed (résolution)', journal);
  }
  return { doi, pmid, pmcid };
}

/**
 * Enrichit à partir d'un DOI (ou d'un PMID).
 *
 * Les quatre sources sont interrogées en parallèle et de façon tolérante :
 * une API en panne dégrade la fiche, elle n'interrompt pas la capture. C'est
 * la contrainte des quinze secondes qui impose ce choix — une capture
 * abandonnée est une capture perdue, une fiche incomplète se corrige.
 */
export async function enrichir(saisie, options = {}) {
  const { email, traductions = {}, tagsMax = 8, titreIndice = null } = options;
  const journal = [];
  const entree = analyserEntree(saisie);

  if (entree.genre === 'inconnu') {
    // Ni DOI, ni identifiant, ni adresse : c'est peut-être un titre collé.
    // C'est la seule voie qui reste pour les éditeurs dont l'adresse ne porte
    // aucun identifiant et qui refusent la lecture automatisée — JAMA et
    // Cambridge notamment, où coller le lien ne donne rien.
    const candidat = String(saisie ?? '').trim();
    if (candidat.split(/\s+/).length >= 5) {
      const trouve = await tolerant(
        crossref.chercherParTitre(candidat, { email }),
        'crossref (par titre)',
        journal,
      );
      if (trouve) {
        const resultat = await enrichir(trouve.doi, options);
        resultat.diagnostics.retrouve_par_titre = { ressemblance: trouve.ressemblance, titre: trouve.titre };
        return resultat;
      }
      return brouillonVide({
        raison: 'aucune référence ne correspond à ce titre',
        journal,
        titre: candidat,
      });
    }
    return brouillonVide({ raison: 'aucun identifiant reconnu dans la saisie' });
  }

  // Une URL dont on n'a pas su tirer d'identifiant. Avant d'abandonner sur un
  // formulaire vide, on tente le titre de la page quand on l'a — c'est le cas
  // depuis le favori de capture et depuis le partage Android, qui le
  // transmettent tous deux.
  if (entree.genre === 'url') {
    // Avant tout, l'identifiant Elsevier : une adresse ScienceDirect ou
    // Lancet ne porte pas de DOI, mais porte un PII qui y mène. Sans cette
    // étape, coller un lien ScienceDirect ouvre un formulaire vide alors que
    // la référence est parfaitement retrouvable.
    const identifiant = piiDepuisUrl(entree.url);
    if (identifiant) {
      const doi =
        identifiant.famille === 'lancet'
          ? normaliserDoi(`10.1016/${identifiant.pii}`)
          : await tolerant(
              crossref.chercherParIdentifiantAlternatif(identifiant.pii, { email }),
              'crossref (identifiant éditeur)',
              journal,
            );
      if (doi) {
        const resultat = await enrichir(doi, { ...options, titreIndice: null });
        // Le lien d'origine est conservé : c'est la page réellement lue,
        // parfois assortie d'une clé d'accès.
        resultat.fiche.lien = entree.url ?? resultat.fiche.lien;
        resultat.diagnostics.resolu_par = `identifiant ${identifiant.famille}`;
        return resultat;
      }
    }

    if (titreIndice) {
      const trouve = await tolerant(
        crossref.chercherParTitre(titreIndice, { email }),
        'crossref (par titre)',
        journal,
      );
      if (trouve) {
        const resultat = await enrichir(trouve.doi, { ...options, titreIndice: null });
        resultat.diagnostics.retrouve_par_titre = { ressemblance: trouve.ressemblance, titre: trouve.titre };
        // Le lien d'origine est conservé : il mène à la page que j'ai
        // réellement lue, qui n'est pas toujours celle du DOI.
        resultat.fiche.lien = entree.url ?? resultat.fiche.lien;
        return resultat;
      }
    }
    return {
      // Le titre de la page, s'il existe, vaut mieux qu'un champ vide : même
      // approximatif, il évite de tout retaper.
      fiche: { type: 'ressource', lien: entree.url, titre: titreIndice ?? '', tags: [], auteurs: [] },
      tags: { suggeres: [], complementaires: [], non_traduits: [] },
      diagnostics: { journal, sources: [], mode: 'manuel' },
    };
  }

  const { doi, pmid, pmcid } = await resoudreIdentifiants(entree, journal);
  if (!doi && !pmid) return brouillonVide({ raison: 'identifiant non résolu', journal, lien: entree.url });

  const [meta, notice, oa, alex] = await Promise.all([
    doi ? tolerant(crossref.chercherParDoi(doi, { email }), 'crossref', journal) : null,
    pmid ? tolerant(pubmed.chercherParPmid(pmid), 'pubmed', journal) : null,
    doi && email ? tolerant(unpaywall.chercherParDoi(doi, { email }), 'unpaywall', journal) : null,
    doi ? tolerant(openalex.chercherParDoi(doi, { email }), 'openalex', journal) : null,
  ]);

  const fiche = fusionner({ doi, pmid, pmcid, meta, notice, oa, alex, lienSaisi: entree.url });
  const tags = suggererTags({
    mesh: notice?.mesh ?? [],
    concepts: alex?.concepts ?? [],
    traductions,
    max: tagsMax,
  });

  return {
    fiche,
    tags,
    diagnostics: {
      journal,
      sources: [meta && 'crossref', notice && 'pubmed', oa && 'unpaywall', alex && 'openalex'].filter(Boolean),
      mode: 'automatique',
    },
  };
}

/**
 * Fusionne les quatre sources en une fiche.
 *
 * L'ordre de préférence n'est pas arbitraire :
 *   - titre, auteurs, pagination : Crossref, qui tient l'enregistrement
 *     officiel déposé par l'éditeur ;
 *   - revue : Crossref également, parce que PubMed sert l'abrégé MEDLINE
 *     (« J Psychiatr Res ») là où on veut le titre complet à afficher ;
 *   - abstract : PubMed, dont le découpage en sections est conservé, puis
 *     OpenAlex, puis Crossref en dernier recours (JATS mal nettoyé).
 */
function fusionner({ doi, pmid, pmcid, meta, notice, oa, alex, lienSaisi }) {
  const titre = premier(meta?.titre, notice?.titre, alex?.titre) ?? '';
  const sousTitre = meta?.sous_titre;

  return {
    titre: sousTitre && !titre.includes(sousTitre) ? `${titre} : ${sousTitre}` : titre,
    type: meta?.type ?? 'article',
    lien: premier(urlDoi(doi), urlPubmed(pmid), lienSaisi) ?? '',
    tags: [],
    doi: doi ?? null,
    pmid: pmid ?? null,
    pmcid: pmcid ?? notice?.pmcid ?? null,
    auteurs: premier(meta?.auteurs, notice?.auteurs) ?? [],
    revue: premier(meta?.revue, notice?.revue, alex?.revue),
    annee: premier(meta?.annee, notice?.annee, alex?.annee),
    volume: premier(meta?.volume, notice?.volume),
    numero: premier(meta?.numero, notice?.numero),
    pages: premier(meta?.pages, notice?.pages),
    abstract: premier(notice?.abstract, alex?.abstract, meta?.abstract),
    // Ce lien remplace le PDF qu'on ne publiera pas (§3.7).
    lien_libre: oa?.libre ? premier(oa.url, alex?.url_libre) : premier(alex?.libre ? alex.url_libre : null),
    sources: [meta && 'crossref', notice && 'pubmed', oa && 'unpaywall', alex && 'openalex'].filter(Boolean),
  };
}

function brouillonVide({ raison, journal = [], lien = null, titre = '' }) {
  return {
    // Le titre saisi est conservé même quand la recherche n'a rien donné :
    // c'est autant de moins à retaper.
    fiche: { type: 'ressource', titre, lien: lien ?? '', tags: [], auteurs: [] },
    tags: { suggeres: [], complementaires: [], non_traduits: [] },
    diagnostics: { journal, sources: [], mode: 'manuel', raison },
  };
}

/**
 * Enrichissement à partir du texte extrait d'un PDF.
 *
 * On ne cherche pas à lire les métadonnées du PDF, qui sont notoirement
 * fausses (titre = « Microsoft Word - final_v3.doc » est un classique). On y
 * cherche un DOI, et on rebranche sur le chemin normal ; le PDF n'est qu'un
 * moyen d'obtenir un identifiant.
 *
 * En dernier recours, on interroge Crossref par le titre présumé, avec un
 * seuil de confiance élevé — une fausse correspondance silencieuse produirait
 * une fiche plausible mais fausse, bien pire qu'un champ vide.
 */
export async function enrichirDepuisTexte(texte, options = {}) {
  const dois = extraireDois(texte);
  if (dois.length) {
    const resultat = await enrichir(dois[0], options);
    if (dois.length > 1) {
      resultat.diagnostics.dois_alternatifs = dois.slice(1, 5);
    }
    return resultat;
  }

  const titrePresume = premiereLigneUtile(texte);
  if (titrePresume) {
    const trouve = await tolerant(
      crossref.chercherParTitre(titrePresume, { email: options.email }),
      'crossref (par titre)',
      [],
    );
    if (trouve) {
      const resultat = await enrichir(trouve.doi, options);
      resultat.diagnostics.retrouve_par_titre = { score: trouve.score, titre: trouve.titre };
      return resultat;
    }
  }

  return brouillonVide({ raison: 'aucun DOI dans le PDF ; saisie manuelle nécessaire' });
}

/** Heuristique de titre : la première ligne assez longue des premières lignes. */
function premiereLigneUtile(texte) {
  const lignes = String(texte ?? '').split('\n').map((l) => l.trim()).slice(0, 40);
  return lignes.find((l) => l.length >= 30 && l.length <= 300 && /[a-z]/.test(l)) ?? null;
}
